/** audio: see docs/architecture.md for ownership and compatibility rules. */
function createAudio({ state, app }) {
    const bgMusic = document.getElementById('bg-music');
    bgMusic.volume = 0.4;
    const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

    function playSynth(type) {
        if (audioCtx.state === 'suspended') audioCtx.resume();
        const now = audioCtx.currentTime;
        const o = audioCtx.createOscillator(), g = audioCtx.createGain();
        o.connect(g).connect(audioCtx.destination);
        g.gain.value = 0.15; let duration = 0.18;
        if (type === 'lane') { o.type = 'sine'; o.frequency.setValueAtTime(660, now); o.frequency.linearRampToValueAtTime(880, now + duration); }
        else if (type === 'jump') { o.type = 'triangle'; o.frequency.setValueAtTime(440, now); o.frequency.linearRampToValueAtTime(1320, now + 0.22); duration = 0.22; }
        else if (type === 'squat') { o.type = 'triangle'; o.frequency.setValueAtTime(660, now); o.frequency.linearRampToValueAtTime(220, now + 0.22); duration = 0.22; }
        else if (type === 'hit') { o.type = 'sawtooth'; o.frequency.setValueAtTime(110, now); o.frequency.linearRampToValueAtTime(55, now + 0.18); g.gain.setValueAtTime(0.2, now); g.gain.linearRampToValueAtTime(0, now + 0.18); }
        else if (type === 'levelup') { o.type = 'square'; o.frequency.setValueAtTime(880, now); o.frequency.linearRampToValueAtTime(1760, now + 0.25); duration = 0.25; }
        else if (type === 'orb') { o.type = 'sine'; o.frequency.setValueAtTime(880, now); o.frequency.linearRampToValueAtTime(1320, now + 0.15); g.gain.setValueAtTime(0.2, now); g.gain.linearRampToValueAtTime(0, now + 0.2); duration = 0.2; }
        else if (type === 'heart') { o.type = 'sine'; o.frequency.setValueAtTime(660, now); o.frequency.linearRampToValueAtTime(990, now + 0.1); o.frequency.linearRampToValueAtTime(1320, now + 0.2); g.gain.setValueAtTime(0.2, now); g.gain.linearRampToValueAtTime(0, now + 0.25); duration = 0.25; }
        else if (type === 'shield') { o.type = 'triangle'; o.frequency.setValueAtTime(440, now); o.frequency.linearRampToValueAtTime(880, now + 0.15); o.frequency.linearRampToValueAtTime(1760, now + 0.3); g.gain.setValueAtTime(0.25, now); g.gain.linearRampToValueAtTime(0, now + 0.4); duration = 0.4; }
        o.start(now); o.stop(now + duration);
        o.onended = () => { o.disconnect(); g.disconnect(); };
    }

    return { bgMusic, audioCtx, playSynth };
}

// Source: src/input/pose-inference.js
/** Runs only inside a dedicated classic worker (including MediaPipe's WASM loader). */
function poseWorkerRuntime() {
    let landmarker;
    self.onmessage = async ({ data }) => {
        const { type, id, bitmap, timestamp } = data;
        try {
            if (type === 'init') {
                let vision;
                try {
                    vision = await import("https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/+esm");
                } catch (error) {
                    vision = await import("https://cdn.skypack.dev/@mediapipe/tasks-vision@0.10.3");
                }
                const files = await vision.FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm');
                const options = {
                    baseOptions: {
                        modelAssetPath: 'https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/1/pose_landmarker_lite.task',
                        delegate: 'GPU'
                    },
                    runningMode: 'VIDEO',
                    numPoses: 4
                };
                let delegate = 'GPU';
                try {
                    options.canvas = new OffscreenCanvas(256, 256);
                    landmarker = await vision.PoseLandmarker.createFromOptions(files, options);
                } catch (error) {
                    // Machines without worker WebGL still infer off the UI thread.
                    delegate = 'CPU';
                    options.baseOptions.delegate = delegate;
                    delete options.canvas;
                    landmarker = await vision.PoseLandmarker.createFromOptions(files, options);
                }
                self.postMessage({ type: 'ready', id, delegate });
            } else if (type === 'frame') {
                const start = performance.now();
                const results = landmarker.detectForVideo(bitmap, timestamp);
                self.postMessage({ type: 'result', id, landmarks: results.landmarks,
                    inferenceMs: Math.round((performance.now() - start) * 10) / 10 });
            }
        } catch (error) {
            self.postMessage({ type: 'error', id, message: String(error) });
        } finally {
            bitmap?.close();
        }
    };
}

/** Owns worker lifecycle and one outstanding request; never queues camera frames. */
function createPoseInference({ app }) {
    let worker, pending, initialization, ready = false, nextId = 0, framePending = false;

    function fail(error) {
        ready = false;
        worker?.terminate();
        worker = undefined;
        if (pending) {
            clearTimeout(pending.timer);
            const reject = pending.reject;
            pending = undefined;
            reject(error);
        }
    }

    function request(message, transfers = [], timeout = 10000) {
        return new Promise((resolve, reject) => {
            const id = ++nextId;
            pending = { id, resolve, reject,
                timer: setTimeout(() => fail(new Error('Body tracking worker timed out')), timeout) };
            try { worker.postMessage({ ...message, id }, transfers); }
            catch (error) { fail(error); }
        });
    }

    function initializePoseInference() {
        if (ready) return Promise.resolve();
        if (initialization) return initialization;
        initialization = (async () => {
            const url = URL.createObjectURL(new Blob([`(${poseWorkerRuntime.toString()})();`], { type: 'text/javascript' }));
            try { worker = new Worker(url); }
            finally { URL.revokeObjectURL(url); }
            worker.onmessage = ({ data }) => {
                if (!pending || data.id !== pending.id) return;
                const current = pending;
                pending = undefined;
                clearTimeout(current.timer);
                if (data.type === 'error') current.reject(new Error(data.message));
                else current.resolve(data);
            };
            worker.onerror = event => {
                event.preventDefault();
                fail(new Error(event.message || 'Body tracking worker failed'));
            };
            worker.onmessageerror = () => fail(new Error('Body tracking worker returned an unreadable result'));
            const result = await request({ type: 'init' }, [], 30000);
            ready = true;
            app.debug.record('camera.worker.ready', { delegate: result.delegate });
        })().catch(error => { fail(error); throw error; }).finally(() => { initialization = undefined; });
        return initialization;
    }

    async function inferPose(bitmap, timestamp) {
        if (framePending) { bitmap.close(); throw new Error('Body tracking worker is busy'); }
        framePending = true;
        try {
            await initializePoseInference();
            return await request({ type: 'frame', bitmap, timestamp }, [bitmap]);
        } catch (error) {
            // Closing a transferred bitmap is harmless; capture/transfer failures
            // must also release the main-thread copy.
            bitmap.close();
            throw error;
        } finally {
            framePending = false;
        }
    }

    return { initializePoseInference, inferPose };
}

// Source: src/input/camera.js
/** camera: see docs/architecture.md for ownership and compatibility rules. */
function createCamera({ state, app }) {
    const videoElement = document.getElementById('webcam-video');
    let lastVideoTime = -1;
    let cameraFrameId = null;
    let trackingError = false;
    let playbackError = false;
    let inferenceMs = 0;
    let inferencePending = false;
    let inferenceWork;
    let poseGeneration = 0;
    let lastObservedTime = -1;

    function invalidatePoseFrame() { poseGeneration++; }
    document.addEventListener('visibilitychange', invalidatePoseFrame);

    function scheduleCameraFrame() {
        if (!state.session.isCameraInitialized || cameraFrameId !== null) return;
        cameraFrameId = requestAnimationFrame(() => {
            cameraFrameId = null;
            predictWebcam();
        });
    }

    async function startVideoPlayback() {
        videoElement.muted = true;
        videoElement.playsInline = true;
        videoElement.classList.remove('hidden');
        await videoElement.play();
        playbackError = false;
        app.debug.record('camera.playing', readCameraStatus());
        scheduleCameraFrame();
    }

    async function initCameraSequence() {
        try {
            await app.poseInference.initializePoseInference();
        } catch(e) {
            app.debug.record('camera.model.error', { message: String(e) });
            console.error("AI Load Error:", e);
            alert("Failed to load AI engine. Please check your internet connection.");
            document.getElementById('loading-screen').classList.add('hidden');
            document.getElementById('dashboard-screen').classList.remove('hidden');
            return;
        }

        if (!state.session.isCameraInitialized) {
            try {
                const stream = await navigator.mediaDevices.getUserMedia({ video: { width: 640, height: 480 } });
                videoElement.srcObject = stream;
                state.session.isCameraInitialized = true;
                app.debug.record('camera.acquired', readCameraStatus());
            } catch (err) {
                app.debug.record('camera.acquire.error', { message: String(err) });
                alert("Camera access is required. Please check your browser permissions.");
                document.getElementById('loading-screen').classList.add('hidden');
                document.getElementById('dashboard-screen').classList.remove('hidden');
                return;
            }
        }

        try {
            // Explicit playback also handles an existing stream paused by the
            // browser. Start one loop after playback, not only on loadeddata.
            await startVideoPlayback();
        } catch (error) {
            playbackError = true;
            app.debug.record('camera.playback.error', { message: String(error) });
            console.error('Camera playback failed:', error);
            alert('Camera video could not start. Please check your camera and try again.');
            document.getElementById('loading-screen').classList.add('hidden');
            document.getElementById('dashboard-screen').classList.remove('hidden');
            return;
        }

        document.getElementById('loading-screen').classList.add('hidden');
        document.getElementById('warning-screen').classList.remove('hidden');
    }

    // Camera mirror canvases
    const camSingle = document.getElementById('cam-single');
    const camLeft   = document.getElementById('cam-left');
    const camRight  = document.getElementById('cam-right');
    const ctxCamSingle = camSingle.getContext('2d');
    const ctxCamLeft   = camLeft.getContext('2d');
    const ctxCamRight  = camRight.getContext('2d');
    const camCalibration = document.getElementById('cam-calibration');
    const ctxCalibration = camCalibration.getContext('2d');
    const calibrationStatus = document.getElementById('calibration-camera-status');

    function showCalibrationPreview() {
        // Re-entry must show this run's live image, never a cached prior frame.
        ctxCalibration.clearRect(0, 0, camCalibration.width, camCalibration.height);
        calibrationStatus.hidden = false;
        camSingle.classList.add('hidden');
        document.getElementById('split-cam-container').style.display = 'none';
        if (state.session.isCameraInitialized && videoElement.paused) {
            startVideoPlayback().catch(error => {
                playbackError = true;
                app.debug.record('camera.playback.error', { message: String(error) });
                console.error('Camera playback failed:', error);
                drawCameraFeeds();
            });
        }
        scheduleCameraFrame();
        drawCameraFeeds();
    }

    function refreshCalibrationCameraStatus() {
        if (!['pre-calibrating', 'calibrating'].includes(state.game.gameState) || videoElement.readyState < 2 || videoElement.paused || videoElement.ended) return;
        calibrationStatus.textContent = trackingError
            ? 'Camera is live, but body tracking is unavailable. Try recalibrating.' : 'Waiting for camera...';
        calibrationStatus.hidden = !trackingError;
    }

    function drawCameraFeeds() {
        const calibrating = ['pre-calibrating', 'calibrating'].includes(state.game.gameState);
        if (!state.session.isCameraInitialized || videoElement.readyState < 2 || videoElement.paused || videoElement.ended) {
            if (calibrating) {
                ctxCalibration.clearRect(0, 0, camCalibration.width, camCalibration.height);
                calibrationStatus.textContent = playbackError
                    ? 'Camera video could not start. Go back and start the camera again.' : 'Waiting for camera...';
                calibrationStatus.hidden = false;
            }
            return;
        }
        const vw = videoElement.videoWidth || 640;
        const vh = videoElement.videoHeight || 480;
        if (calibrating) {
            // The full frame keeps both players visible; CSS mirrors only the
            // presentation, leaving pose coordinates and player matching intact.
            if (camCalibration.width !== vw) camCalibration.width = vw;
            if (camCalibration.height !== vh) camCalibration.height = vh;
            ctxCalibration.drawImage(videoElement, 0, 0, vw, vh);
            refreshCalibrationCameraStatus();
        }

        if (state.session.numPlayers === 1) {
            ctxCamSingle.drawImage(videoElement, 0, 0, camSingle.width, camSingle.height);
        } else {
            // cam-left (left side of screen) → RIGHT half of raw video (shows person standing on left)
            ctxCamLeft.save();
            ctxCamLeft.translate(camLeft.width, 0);
            ctxCamLeft.scale(-1, 1);
            ctxCamLeft.drawImage(videoElement, vw / 2, 0, vw / 2, vh, 0, 0, camLeft.width, camLeft.height);
            ctxCamLeft.restore();

            // cam-right (right side of screen) → LEFT half of raw video (shows person standing on right)
            ctxCamRight.save();
            ctxCamRight.translate(camRight.width, 0);
            ctxCamRight.scale(-1, 1);
            ctxCamRight.drawImage(videoElement, 0, 0, vw / 2, vh, 0, 0, camRight.width, camRight.height);
            ctxCamRight.restore();
        }
    }

    function showCameraForMode() {
        if (state.session.numPlayers === 1) {
            camSingle.classList.remove('hidden');
            document.getElementById('split-cam-container').style.display = 'none';
        } else {
            camSingle.classList.add('hidden');
            document.getElementById('split-cam-container').style.display = 'flex';
        }
    }

    function reportInferenceError(error) {
        if (!trackingError) {
            console.error('Body tracking failed:', error);
            app.debug.record('camera.inference.error', { message: String(error), stack: String(error.stack || '').slice(0, 2000) });
        }
        trackingError = true;
        app.pose.onPoseResults({ landmarks: [] });
    }

    function predictWebcam() {
        let work;
        try {
            if (state.session.isCameraInitialized && !document.hidden &&
                ['playing', 'calibrating', 'pre-calibrating'].includes(state.game.gameState) &&
                videoElement.readyState >= 2 && !videoElement.paused && !videoElement.ended) {
                const videoTime = videoElement.currentTime;
                if (videoTime < lastObservedTime) { invalidatePoseFrame(); lastVideoTime = -1; }
                lastObservedTime = videoTime;
                if (lastVideoTime !== videoTime && !inferencePending) {
                    lastVideoTime = videoTime;
                    const capturedAt = performance.now();
                    const generation = poseGeneration;
                    const phase = state.game.gameState;
                    const count = state.session.numPlayers;
                    inferencePending = true;
                    // Capture/transfer one frame. While it runs, preview and game
                    // callbacks continue; the next request takes the newest video.
                    work = createImageBitmap(videoElement).then(bitmap => app.poseInference.inferPose(bitmap, capturedAt))
                        .then(result => {
                            const age = performance.now() - capturedAt;
                            if (generation !== poseGeneration || phase !== state.game.gameState || count !== state.session.numPlayers) return;
                            if (document.hidden || videoElement.paused || videoElement.ended ||
                                videoElement.currentTime < videoTime || age < 0 || age > 250) {
                                reportInferenceError(new Error('Body tracking frame is stale'));
                                return;
                            }
                            inferenceMs = result.inferenceMs;
                            trackingError = false;
                            app.pose.onPoseResults({ landmarks: result.landmarks || [] });
                            app.debug.sample('camera.frame', readCameraStatus());
                            app.debugPanel.drawDebugFrame(videoElement, result.landmarks || [], app.playerTracking.trackingReport());
                        }).catch(error => {
                            if (generation === poseGeneration && phase === state.game.gameState && count === state.session.numPlayers) reportInferenceError(error);
                        }).finally(() => {
                            inferencePending = false;
                            inferenceWork = undefined;
                            refreshCalibrationCameraStatus();
                        });
                    inferenceWork = work;
                }
            }
        } catch (error) {
            inferencePending = false;
            reportInferenceError(error);
        } finally {
            try { drawCameraFeeds(); }
            finally { scheduleCameraFrame(); }
        }
        return work || inferenceWork;
    }

    function readCameraStatus() {
        const track = videoElement.srcObject?.getVideoTracks()[0];
        const settings = track?.getSettings() || {};
        return { initialized: state.session.isCameraInitialized, readyState: videoElement.readyState,
            paused: videoElement.paused, ended: videoElement.ended, videoTime: videoElement.currentTime,
            width: videoElement.videoWidth, height: videoElement.videoHeight, frameRate: settings.frameRate,
            trackState: track?.readyState, inferenceMs, trackingError, playbackError };
    }

    return { videoElement, invalidatePoseFrame, initCameraSequence, camSingle, camLeft, camRight, ctxCamSingle, ctxCamLeft, ctxCamRight, drawCameraFeeds, showCalibrationPreview, showCameraForMode, predictWebcam, readCameraStatus };
}

// Source: src/input/arm-postures.js
/** Camera-space geometry for the extended, level-arm duck gesture. */
function createArmPostures({ app }) {
    const MIN_CONFIDENCE = 0.6;
    const MAX_WRIST_ANGLE = 20;
    const MAX_ELBOW_ANGLE = 25;
    const MIN_EXTENSION_ANGLE = 150;

    function tracked(point) {
        return point && Number.isFinite(point.x) && Number.isFinite(point.y) &&
            ['visibility', 'presence'].every(key => point[key] === undefined ||
                (Number.isFinite(point[key]) && point[key] >= MIN_CONFIDENCE));
    }

    function readLevelArms(landmarks) {
        if (![11,12,13,14,15,16].every(index => tracked(landmarks?.[index]))) {
            return { detected: false, reason: 'visibility' };
        }
        const video = app.camera.videoElement;
        const aspect = (video.videoWidth || 640) / (video.videoHeight || 480);
        const point = index => ({ x: landmarks[index].x * aspect, y: landmarks[index].y });
        const leftShoulder = point(11), rightShoulder = point(12);
        const span = Math.hypot(leftShoulder.x - rightShoulder.x, leftShoulder.y - rightShoulder.y);
        if (span < 0.03 || Math.abs(leftShoulder.x - rightShoulder.x) < 0.03) {
            return { detected: false, reason: 'shoulders' };
        }

        function arm(shoulder, otherShoulder, elbow, wrist) {
            const outward = Math.sign(shoulder.x - otherShoulder.x);
            const wristX = (wrist.x - shoulder.x) * outward;
            const elbowX = (elbow.x - shoulder.x) * outward;
            const wristAngle = Math.atan2(Math.abs(wrist.y - shoulder.y), wristX) * 180 / Math.PI;
            const elbowAngle = Math.atan2(Math.abs(elbow.y - shoulder.y), elbowX) * 180 / Math.PI;
            const upper = { x: shoulder.x - elbow.x, y: shoulder.y - elbow.y };
            const forearm = { x: wrist.x - elbow.x, y: wrist.y - elbow.y };
            const length = Math.hypot(upper.x, upper.y) * Math.hypot(forearm.x, forearm.y);
            const extension = length > 0 ? Math.acos(Math.max(-1, Math.min(1,
                (upper.x * forearm.x + upper.y * forearm.y) / length))) * 180 / Math.PI : 0;
            const extended = wristX >= span * 0.65 && elbowX >= span * 0.2 && extension >= MIN_EXTENSION_ANGLE;
            const level = wristAngle <= MAX_WRIST_ANGLE && elbowAngle <= MAX_ELBOW_ANGLE;
            return { detected: extended && level, extended, level, wristAngle, elbowAngle,
                extension, outwardShoulderWidths: wristX / span };
        }

        const left = arm(leftShoulder, rightShoulder, point(13), point(15));
        const right = arm(rightShoulder, leftShoulder, point(14), point(16));
        return { detected: left.detected && right.detected, left, right };
    }

    return { readLevelArms };
}

// Source: src/input/lane-gestures.js
/** One lane intent per arm-raise cycle, tracked separately for each player. */
function createLaneGestures({ app }) {
    const REARM_DEGREES = 15;
    const ANGLE_EPSILON = 1e-6;
    const LOWER_HOLD_MS = 150;
    const RAISE_HOLD_MS = 60;
    const MIN_STABLE_SAMPLES = 3;
    const MIN_CONFIDENCE = 0.6;
    const MAX_SAMPLE_GAP_MS = 250;
    const gesturesByPlayer = new WeakMap();

    function resetLaneGestures(player) {
        gesturesByPlayer.delete(player);
    }

    function discardEvidence(gesture) {
        gesture.samples = [];
        gesture.confirmation = null;
        // Uncertain tracking must not turn a previously lowered arm into a
        // fresh raise on reacquisition. Keep the latch and require a new release.
        if (gesture.phase === 'lowered') gesture.phase = 'holding';
    }

    function interruptLaneGestures(player) {
        const gestures = gesturesByPlayer.get(player);
        if (!gestures) return;
        discardEvidence(gestures.left);
        discardEvidence(gestures.right);
        gestures.lastSampleAt = undefined;
    }

    function isTracked(point) {
        return point && Number.isFinite(point.x) && Number.isFinite(point.y) &&
            ['visibility', 'presence'].every(key => point[key] === undefined ||
                (Number.isFinite(point[key]) && point[key] >= MIN_CONFIDENCE));
    }

    function armAngle(shoulder, wrist) {
        const video = app.camera.videoElement;
        const width = video.videoWidth || 640;
        const height = video.videoHeight || 480;
        const horizontal = Math.abs(wrist.x - shoulder.x) * width;
        const vertical = (shoulder.y - wrist.y) * height;
        if (!Number.isFinite(horizontal) || !Number.isFinite(vertical) || horizontal + Math.abs(vertical) === 0) return NaN;
        return Math.atan2(vertical, horizontal) * 180 / Math.PI;
    }

    function stableFor(gesture, kind, now, duration) {
        if (gesture.confirmation?.kind !== kind) {
            gesture.confirmation = { kind, since: now, samples: 0 };
        }
        const confirmation = gesture.confirmation;
        confirmation.samples++;
        return confirmation.samples >= MIN_STABLE_SAMPLES && now - confirmation.since >= duration;
    }

    function latch(gesture, angle) {
        gesture.phase = 'holding';
        gesture.peak = angle;
        gesture.confirmation = null;
    }

    function confirmRaise(gesture, angle, raised, enabled, now) {
        if (!raised) {
            gesture.confirmation = null;
            return false;
        }
        if (!enabled) {
            latch(gesture, angle);
            return false;
        }
        if (!stableFor(gesture, 'raise', now, RAISE_HOLD_MS)) return false;
        latch(gesture, angle);
        return true;
    }

    function updateArm(gesture, rawAngle, raised, enabled, now) {
        if (!Number.isFinite(rawAngle)) {
            discardEvidence(gesture);
            return false;
        }
        // A rolling median rejects an isolated spike without allowing that
        // spike to become a new peak or a new lowest release angle.
        gesture.samples.push(rawAngle);
        if (gesture.samples.length > 3) gesture.samples.shift();
        if (gesture.samples.length < 3) {
            if (raised && !enabled) latch(gesture, rawAngle);
            return false;
        }
        const angle = [...gesture.samples].sort((a, b) => a - b)[1];

        if (gesture.phase === 'ready') {
            return confirmRaise(gesture, angle, raised, enabled, now);
        }

        if (gesture.phase === 'holding') {
            gesture.peak = Math.max(gesture.peak, angle);
            if (gesture.peak - angle + ANGLE_EPSILON >= REARM_DEGREES) {
                if (stableFor(gesture, 'lower', now, LOWER_HOLD_MS)) {
                    gesture.phase = 'lowered';
                    gesture.low = angle;
                    gesture.confirmation = null;
                }
            } else gesture.confirmation = null;
            return false;
        }

        gesture.low = Math.min(gesture.low, angle);
        if (raised && angle - gesture.low + ANGLE_EPSILON >= REARM_DEGREES) {
            return confirmRaise(gesture, angle, raised, enabled, now);
        }
        gesture.confirmation = null;
        return false;
    }

    function detectLaneGesture(player, landmarks, leftRaised, rightRaised, enabled) {
        let gestures = gesturesByPlayer.get(player);
        if (!gestures) {
            gestures = { left: { phase: 'ready', samples: [] }, right: { phase: 'ready', samples: [] } };
            gesturesByPlayer.set(player, gestures);
        }
        const now = performance.now();
        if (![11, 12, 15, 16].every(index => isTracked(landmarks[index]))) {
            interruptLaneGestures(player);
            return 0;
        }
        if (gestures.lastSampleAt !== undefined &&
            (now < gestures.lastSampleAt || now - gestures.lastSampleAt > MAX_SAMPLE_GAP_MS)) {
            interruptLaneGestures(player);
        }
        gestures.lastSampleAt = now;
        // Even blocked poses consume raises, so leaving a squat/jump/rest cannot
        // turn a held arm into a delayed lane change.
        const left = updateArm(gestures.left, armAngle(landmarks[11], landmarks[15]), leftRaised, enabled && !rightRaised, now);
        const right = updateArm(gestures.right, armAngle(landmarks[12], landmarks[16]), rightRaised, enabled && !leftRaised, now);
        return left ? -1 : right ? 1 : 0;
    }

    return { detectLaneGesture, resetLaneGestures, interruptLaneGestures };
}

// Source: src/input/player-tracking.js
/** Calibration-owned player slots. Unmatched poses never enroll during play. */
function createPlayerTracking({ state, app }) {
    const MIN_CONFIDENCE = 0.6;
    const STALE_MS = 500;
    const REACQUIRE_MS = 300;
    const LONG_LOSS_MS = 2000;
    const EXTENDED_REACQUIRE_MS = 1000;
    const AMBIGUITY_MARGIN = 0.35;
    let tracks = [];
    let frameId = 0;
    let report = { frameId: 0, rawCount: 0, validCount: 0, selected: [], accepted: [], ignored: [], costs: [], candidates: [] };

    function resetEnrollment() {
        tracks = [];
        report = { frameId: ++frameId, rawCount: 0, validCount: 0, selected: [], accepted: [], ignored: [], costs: [], candidates: [] };
    }

    function describe(landmarks, index) {
        const indices = [11, 12, 23, 24];
        if (!indices.every(index => {
            const point = landmarks?.[index];
            return point && Number.isFinite(point.x) && Number.isFinite(point.y) &&
                ['visibility', 'presence'].every(key => point[key] === undefined ||
                    (Number.isFinite(point[key]) && point[key] >= MIN_CONFIDENCE));
        })) return null;
        const video = app.camera.videoElement;
        const aspect = (video.videoWidth || 640) / (video.videoHeight || 480);
        const points = indices.map(index => ({ x: landmarks[index].x * aspect, y: landmarks[index].y }));
        const midpoint = (a, b) => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });
        const shoulders = midpoint(points[0], points[1]);
        const center = midpoint(points[2], points[3]);
        const shoulderWidth = Math.hypot(points[0].x - points[1].x, points[0].y - points[1].y);
        const hipWidth = Math.hypot(points[2].x - points[3].x, points[2].y - points[3].y);
        const torso = Math.hypot(shoulders.x - center.x, shoulders.y - center.y);
        if (Math.min(shoulderWidth, hipWidth, torso) < 0.03) return null;
        return { index, landmarks, center, shoulderWidth, hipWidth, torso, hipRatio: hipWidth / shoulderWidth };
    }

    function createTrack(candidate, now) {
        return { profile: { shoulderWidth: candidate.shoulderWidth, hipWidth: candidate.hipWidth,
                torso: candidate.torso, hipRatio: candidate.hipRatio },
            center: candidate.center, velocity: { x: 0, y: 0 }, lastSeen: now,
            status: 'tracked', recovery: null, extendedRecovery: false };
    }

    function evaluateMatch(track, candidate, now) {
        const profile = track.profile;
        const widthDifference = Math.abs(Math.log(candidate.shoulderWidth / profile.shoulderWidth));
        const torsoDifference = Math.abs(Math.log(candidate.torso / profile.torso));
        const hipDifference = Math.abs(Math.log(candidate.hipWidth / profile.hipWidth));
        const recovering = track.status !== 'tracked';
        const dt = recovering ? 0 : Math.min(Math.max(now - track.lastSeen, 0), 125) / 1000;
        const predicted = { x: track.center.x + track.velocity.x * dt, y: track.center.y + track.velocity.y * dt };
        const xGate = Math.max(0.12, Math.min(0.3, profile.hipWidth * 1.15));
        const yGate = Math.max(0.25, Math.min(0.4, profile.torso));
        const distance = Math.hypot((candidate.center.x - predicted.x) / xGate, (candidate.center.y - predicted.y) / yGate);
        const recoveryDistance = Math.hypot((candidate.center.x - predicted.x) / (xGate * (recovering ? 0.65 : 1)),
            (candidate.center.y - predicted.y) / (yGate * (recovering ? 0.8 : 1)));
        const evidence = { distance, recoveryDistance, widthDifference, torsoDifference, hipDifference };
        if (distance > 1) return { ...evidence, cost: Infinity, ambiguityCost: Infinity, reason: 'position' };
        // Hip position and bounded motion lead association. Fixed hips/torso
        // reject gross scale changes without treating raised shoulders as a
        // different person. Shoulder width contributes only a capped soft cost.
        if (hipDifference > 0.45 || torsoDifference > 0.6) {
            return { ...evidence, cost: Infinity, ambiguityCost: Infinity, reason: 'body_scale' };
        }
        const cost = distance * 2 + Math.min(widthDifference, 1) * 0.1 +
            Math.min(torsoDifference, 1) * 0.15 + Math.min(hipDifference, 1) * 0.15;
        // Use the same ambiguity scale before/after loss. Narrowing the recovery
        // gate must not make unchanged overlapping people suddenly look distinct.
        return { ...evidence, cost: recoveryDistance > 1 ? Infinity : cost, ambiguityCost: cost,
            reason: recoveryDistance > 1 ? 'recovery_position' : 'plausible' };
    }

    function lose(track, status = 'lost') {
        track.status = status;
        track.recovery = null;
        track.velocity = { x: 0, y: 0 };
        if (status === 'uncertain') track.extendedRecovery = true;
    }

    function expire(now) {
        for (const track of tracks) {
            if (now - track.lastSeen > LONG_LOSS_MS) track.extendedRecovery = true;
            if (now - track.lastSeen > STALE_MS && track.status === 'tracked') lose(track);
        }
    }

    function updateTrack(track, candidate, now) {
        if (track.status !== 'tracked') {
            const recovery = track.recovery;
            // An interrupted or moving candidate must start its confirmation again.
            if (!recovery || now - recovery.lastAt > STALE_MS ||
                Math.hypot(candidate.center.x - recovery.center.x, candidate.center.y - recovery.center.y) > 0.06) {
                track.recovery = { since: now, lastAt: now, center: candidate.center, samples: 1 };
                track.status = 'checking';
                return false;
            }
            // Only fresh observations can advance confirmation. The watchdog
            // never counts as a sample or extends the last trusted position.
            if (now <= recovery.lastAt) return false;
            recovery.lastAt = now;
            recovery.samples++;
            const requiredMs = track.extendedRecovery ? EXTENDED_REACQUIRE_MS : REACQUIRE_MS;
            const requiredSamples = track.extendedRecovery ? 5 : 3;
            if (now - recovery.since < requiredMs || recovery.samples < requiredSamples) return false;
            track.recovery = null;
            track.status = 'tracked';
            track.extendedRecovery = false;
        }
        const dt = Math.max(now - track.lastSeen, 1) / 1000;
        for (const axis of ['x', 'y']) {
            const speed = (candidate.center[axis] - track.center[axis]) / dt;
            track.velocity[axis] = Math.max(-0.6, Math.min(0.6, speed)) * 0.5 + track.velocity[axis] * 0.5;
        }
        track.center = candidate.center;
        track.lastSeen = now;
        return true;
    }

    // Called only after readiness and neutral-pose sampling have completed.
    function lockPlayers(poses) {
        const candidates = poses.map(describe);
        if (candidates.length !== state.session.numPlayers || candidates.some(candidate => !candidate)) return false;
        candidates.sort((a, b) => b.center.x - a.center.x);
        tracks = candidates.map(candidate => createTrack(candidate, performance.now()));
        report = { frameId: ++frameId, rawCount: poses.length, validCount: candidates.length,
            selected: candidates.map(candidate => candidate.index), accepted: candidates.map(candidate => candidate.index),
            ignored: [], costs: [], candidates: [] };
        return true;
    }

    function matchPlayers(poses) {
        const now = performance.now();
        const candidates = poses.map(describe).filter(Boolean);
        expire(now);
        const evidence = tracks.map(track => candidates.map(candidate => evaluateMatch(track, candidate, now)));
        const costs = evidence.map(row => row.map(item => item.cost));
        const ambiguityCosts = evidence.map(row => row.map(item => item.ambiguityCost));
        // Reject an ambiguous row (two plausible people) or column (one body
        // plausibly belongs to both players). Never break ties by detector order.
        const ambiguous = new Set();
        for (let i = 0; i < ambiguityCosts.length; i++) {
            const sorted = ambiguityCosts[i].filter(Number.isFinite).sort((a, b) => a - b);
            if (sorted.length > 1 && sorted[1] - sorted[0] < AMBIGUITY_MARGIN) ambiguous.add(i);
        }
        for (let j = 0; j < candidates.length; j++) {
            const possible = ambiguityCosts.map((row, i) => ({ i, cost: row[j] })).filter(item => Number.isFinite(item.cost));
            if (possible.length > 1) possible.forEach(item => ambiguous.add(item.i));
        }
        const selected = costs.map(row => {
            let best = -1;
            row.forEach((cost, index) => { if (Number.isFinite(cost) && (best < 0 || cost < row[best])) best = index; });
            return best;
        });
        // No two tracks may claim the same candidate, even with unequal costs.
        for (let i = 0; i < selected.length; i++) {
            if (selected[i] >= 0 && selected.some((candidate, other) => other !== i && candidate === selected[i])) ambiguous.add(i);
        }
        report = { frameId: ++frameId, at: now, rawCount: poses.length, validCount: candidates.length,
            selected: selected.map(index => index < 0 ? null : candidates[index].index), ambiguous: [...ambiguous],
            costs: costs.map(row => row.map(cost => Number.isFinite(cost) ? Math.round(cost * 1000) / 1000 : null)),
            ambiguityCosts: ambiguityCosts.map(row => row.map(cost => Number.isFinite(cost) ? Math.round(cost * 1000) / 1000 : null)),
            evidence: evidence.map(row => row.map(({ cost, ambiguityCost, ...item }) => item)),
            candidates: candidates.map(({ index, center, shoulderWidth, hipWidth, torso, hipRatio }) => ({ index, center, shoulderWidth, hipWidth, torso, hipRatio })) };
        const matched = Array.from({ length: state.session.numPlayers }, (_, i) => {
            const track = tracks[i];
            if (!track) return null;
            if (ambiguous.has(i)) { lose(track, 'uncertain'); return null; }
            if (selected[i] < 0) { lose(track); return null; }
            const candidate = candidates[selected[i]];
            return updateTrack(track, candidate, now) ? candidate.landmarks : null;
        });
        report.accepted = matched.map((pose, i) => pose ? report.selected[i] : null);
        // Only call candidates ignored when all locked slots were identified.
        report.ignored = matched.every(Boolean)
            ? poses.map((_, index) => index).filter(index => !report.accepted.includes(index)) : [];
        return matched;
    }

    function trackingStatuses() {
        expire(performance.now());
        return Array.from({ length: state.session.numPlayers }, (_, i) => tracks[i]?.status || 'unregistered');
    }

    function trackingReport() {
        return { ...report, tracks: tracks.map(track => ({ center: track.center, profile: track.profile,
            ageMs: Math.round(performance.now() - track.lastSeen), status: track.status,
            recovery: { mode: track.extendedRecovery ? 'extended' : 'brief',
                requiredMs: track.extendedRecovery ? EXTENDED_REACQUIRE_MS : REACQUIRE_MS,
                elapsedMs: track.recovery ? Math.round(performance.now() - track.recovery.since) : 0,
                samples: track.recovery?.samples || 0 } })) };
    }

    return { resetEnrollment, lockPlayers, matchPlayers, trackingStatuses, trackingReport };
}

