/** pose: see docs/architecture.md for ownership and compatibility rules. */
function createPose({ state, app }) {
    let calibrationActive = false;
    const suspendedPlayers = new WeakSet();
    const laneGateReasons = new WeakMap();

    function beginCalibration() {
        app.camera.invalidatePoseFrame?.();
        app.finishPhoto.resetFinishPhoto();
        app.trackingSafety.resetTrackingSafety();
        app.debug.record('calibration.begin', { expected: state.session.numPlayers });
        app.playerTracking.resetEnrollment();
        app.calibration.resetCalibration();
        app.trackingStatus.clearTrackingStatus();
        app.trackingStatus.resetCalibrationMessages();
        calibrationActive = true;
        for (const player of state.game.players.slice(0, state.session.numPlayers)) {
            player.baseline = 0;
            player.calibrationFrames = 0;
            player.homeX = undefined;
            player.homeXSum = 0;
            app.laneGestures.resetLaneGestures(player);
            suspendedPlayers.delete(player);
            laneGateReasons.delete(player);
        }
    }

    function suspendPlayerInput(player) {
        app.laneGestures.interruptLaneGestures(player);
        player.isJumping = false;
        player.isSquatting = false;
        player.isResting = false;
        player.armsCrossedNow = false;
        player.restingMode = false;
        suspendedPlayers.add(player);
    }

    // Called by the game loop as well as camera callbacks: a stalled camera
    // cannot leave a jump/rest pose active indefinitely.
    function checkPlayerTracking() {
        if (state.game.gameState !== 'playing') return;
        const statuses = app.playerTracking.trackingStatuses();
        const report = app.playerTracking.trackingReport();
        const camera = app.camera.readCameraStatus();
        const safety = app.trackingSafety.updateTrackingSafety(statuses, report, camera);
        statuses.forEach((status, i) => {
            if (safety.paused || (status !== 'tracked' && status !== 'unregistered')) suspendPlayerInput(state.game.players[i]);
        });
        app.trackingStatus.refreshTrackingStatus(statuses, safety, report);
        app.debug.transition('tracking.status', JSON.stringify([statuses, safety, report.rawCount, report.ignored]),
            { statuses, ...safety, report });
        app.debug.sample('tracking.frame', { statuses, ...safety, report, camera });
        app.debug.setDebugStatus({ phase: state.game.gameState, expected: state.session.numPlayers,
            detected: report.rawCount, valid: report.validCount, ignored: report.ignored || [],
            statuses, ...safety, inferenceMs: camera.inferenceMs });
    }

    function onPoseResults(results) {
        const calibrating = state.game.gameState === 'calibrating';
        if (!calibrating && state.game.gameState !== 'playing') return;
        if (app.debug.enabled) {
            const poses = results.landmarks || [];
            app.debug.transition('detection.count', String(poses.length), { detected: poses.length, expected: state.session.numPlayers });
            app.debug.sample('pose.observation', { phase: state.game.gameState, detected: poses.length,
                poses: poses.map(pose => [11, 12, 13, 14, 15, 16, 23, 24].map(id => ({ id, ...pose[id] }))) });
        }
        if (calibrating && !calibrationActive) beginCalibration();
        if (calibrating) {
            const result = app.calibration.updateCalibration(results.landmarks || []);
            app.debug.transition('calibration.status', JSON.stringify([result.phase, result.reason, result.playerIndex,
                result.players?.map(player => player.phase)]),
                { phase: result.phase, reason: result.reason, playerIndex: result.playerIndex,
                    samples: result.samples, progress: result.progress, players: result.players });
            app.debug.setDebugStatus({ phase: `calibration: ${result.phase}`, expected: state.session.numPlayers,
                detected: (results.landmarks || []).length, reason: result.reason, progress: result.progress });
            const guidanceReady = app.trackingStatus.renderCalibration(result);
            if (result.phase === 'complete' && guidanceReady) {
                if (!app.playerTracking.lockPlayers(result.poses)) {
                    app.calibration.resetCalibration();
                    app.trackingStatus.renderCalibration({ phase: 'waiting', reason: 'visibility', progress: 0 });
                    return;
                }
                for (let i = 0; i < state.session.numPlayers; i++) {
                    const pose = result.poses[i];
                    const player = state.game.players[i];
                    player.baseline = (pose[11].y + pose[12].y) / 2;
                    player.homeX = (pose[23].x + pose[24].x) / 2;
                    player.calibrationFrames = result.sampleCounts[i];
                    player.homeXSum = player.homeX * player.calibrationFrames;
                }
                calibrationActive = false;
                app.session.startGameplay();
            }
        } else {
            const poses = app.playerTracking.matchPlayers(results.landmarks || []);
            checkPlayerTracking();
            if (app.trackingSafety.isGameplayPaused()) return;
            app.finishPhoto.observeFinishPlayers(poses);
            for (let i = 0; i < state.session.numPlayers; i++) {
                const player = state.game.players[i];
                if (poses[i] && player.lives > 0) {
                    const resumed = suspendedPlayers.has(player);
                    suspendedPlayers.delete(player);
                    handlePlayerMovement(player, poses[i], !resumed);
                } else suspendPlayerInput(player);
            }
        }
    }

    // Detect arms crossed (resting posture) for shield activation
    function detectArmsCrossed(landmarks) {
        const leftWrist    = landmarks[15];
        const rightWrist   = landmarks[16];
        const leftShoulder = landmarks[11];
        const rightShoulder= landmarks[12];
        const leftElbow    = landmarks[13];
        const rightElbow   = landmarks[14];

        const centerX  = (leftShoulder.x + rightShoulder.x) / 2;
        const shoulderY= (leftShoulder.y + rightShoulder.y) / 2;

        // Because camera is mirrored for display, landmark X is from raw video
        // Left wrist crossing over = leftWrist.x < centerX (moves toward right in raw)
        // Right wrist crossing over = rightWrist.x > centerX
        // Also both wrists should be near chest height (below shoulders by some margin)
        const wristsCrossed = leftWrist.x < centerX && rightWrist.x > centerX;
        const wristsAtChest = leftWrist.y < shoulderY + 0.35 && rightWrist.y < shoulderY + 0.35;
        const elbowsRaised  = leftElbow.y < shoulderY + 0.2 && rightElbow.y < shoulderY + 0.2;

        return wristsCrossed && wristsAtChest && elbowsRaised;
    }

    function handlePlayerMovement(player, landmarks, allowLane = true) {
        if (player.restCooldown > 0) player.restCooldown--;

        const squatThreshold = 0.10, armLevelThreshold = 0.15, armsUpThreshold = -0.15;

        let wasSquatting = player.isSquatting, wasJumping = player.isJumping;
        let wasResting = player.isResting;
        player.isSquatting = false; player.isJumping = false; player.isResting = false;

        const leftShoulder = landmarks[11], rightShoulder = landmarks[12];
        const leftWrist = landmarks[15], rightWrist = landmarks[16];
        const leftArmRaised = leftWrist.y < leftShoulder.y + armLevelThreshold;
        const rightArmRaised = rightWrist.y < rightShoulder.y + armLevelThreshold;
        const bothArmsUp = leftWrist.y < leftShoulder.y + armsUpThreshold && rightWrist.y < rightShoulder.y + armsUpThreshold;
        const levelArms = app.armPostures.readLevelArms(landmarks);
        const bothArmsLevel = levelArms.detected;
        const crouching = (leftShoulder.y + rightShoulder.y) / 2 > player.baseline + squatThreshold;
        const ducking = bothArmsLevel || crouching;
        const duckSource = bothArmsLevel ? 'level_arms' : crouching ? 'crouch' : null;

        // Check arms crossed (resting posture)
        const armsCrossed = detectArmsCrossed(landmarks);
        player.armsCrossedNow = armsCrossed;
        player.restingMode = armsCrossed; // persistent flag for orb collision
        // Active actions block lateral input. Once they end, the confirmed
        // lower/raise cycle provides the guard against accidental lane moves.
        const laneBlockReason = !allowLane ? 'tracking_recovery' : armsCrossed ? 'rest'
            : bothArmsUp ? 'fly' : ducking ? 'duck' : null;
        const canChangeLane = laneBlockReason === null;
        if (app.debug.enabled && laneGateReasons.get(player) !== laneBlockReason) {
            laneGateReasons.set(player, laneBlockReason);
            app.debug.record('input.lane_gate', { player: state.game.players.indexOf(player), blockedBy: laneBlockReason, levelArms, duckSource });
        }
        const laneChange = app.laneGestures.detectLaneGesture(player, landmarks, leftArmRaised, rightArmRaised, canChangeLane);

        if (armsCrossed) {
            player.isResting = true;
            if (player.shieldOrbs >= 5 && !player.shieldActive) {
                player.shieldActive = true;
                player.shieldTimer  = 300;
                player.shieldOrbs -= 5;
                app.hud.updateHUD();
                app.audio.playSynth('shield');
            }
            return;
        } else {
            player.isResting = false;
        }

        if (bothArmsUp) {
            player.isJumping = true;
            if (!wasJumping) { app.energy.recordEnergyAction(player); app.debug.record('input.jump', { player: state.game.players.indexOf(player) }); player.stats.jumps++; app.hud.updateHUD(); app.audio.playSynth('jump'); }
        } else if (ducking) {
            player.isSquatting = true;
            if (!wasSquatting) { app.energy.recordEnergyAction(player); app.debug.record('input.squat', { player: state.game.players.indexOf(player), source: duckSource }); player.stats.squats++; app.hud.updateHUD(); app.audio.playSynth('squat'); }
        }

        if (laneChange !== 0) {
            const nextLane = Math.max(-1, Math.min(1, player.lane + laneChange));
            if (nextLane !== player.lane) {
                app.debug.record('input.lane', { player: state.game.players.indexOf(player), from: player.lane, to: nextLane });
                app.energy.recordEnergyAction(player);
                player.lane = nextLane;
                app.audio.playSynth('lane');
            }
        }
    }

    return { beginCalibration, checkPlayerTracking, onPoseResults, detectArmsCrossed, handlePlayerMovement };
}

// Source: src/ui/controls.js
/** controls: see docs/architecture.md for ownership and compatibility rules. */
function createControls({ state, app }) {
    let calibrationTimeout;

    function startCalibration() {
        clearTimeout(calibrationTimeout);
        app.pose.beginCalibration();
        document.getElementById('calibration-screen').classList.remove('hidden');
        document.getElementById('calibration-bar').style.width = '0%';
        state.game.gameState = 'pre-calibrating';
        app.trackingStatus.showCalibrationPreparation();
        app.camera.showCalibrationPreview();
        calibrationTimeout = setTimeout(() => {
            if (state.game.gameState === 'pre-calibrating') state.game.gameState = 'calibrating';
        }, 1500);
    }

    function bind() {
        document.getElementById('lang-select').addEventListener('change', (e) => app.localization.setLoginLang(e.target.value));
        document.getElementById('lang-btn-en').addEventListener('click', () => app.localization.setLoginLang('en'));
        document.getElementById('lang-btn-mi').addEventListener('click', () => app.localization.setLoginLang('mi'));
        document.getElementById('theme-select').addEventListener('change', (e) => app.preferences.updateTheme(e.target.value));
        document.getElementById('login-theme-toggle').addEventListener('click', () => {
            const next = document.documentElement.classList.contains('dark') ? 'light' : 'dark';
            app.preferences.updateTheme(next);
        });
        document.getElementById('player-name').addEventListener('input', app.localization.updateLoginNameCheck);
        document.getElementById('player-name').addEventListener('keydown', (e) => {
            if (e.key === 'Enter') document.getElementById('btn-continue').click();
        });

        document.getElementById('btn-mode-1p').addEventListener('click', () => {
            state.session.numPlayers = 1; state.game.players[1].active = false;
            document.getElementById('p2-name-input-wrap').classList.add('hidden');
            document.getElementById('btn-mode-1p').classList.replace('border-transparent', 'border-indigo-400');
            document.getElementById('btn-mode-1p').classList.replace('bg-gray-200', 'bg-indigo-600');
            document.getElementById('btn-mode-1p').classList.replace('text-gray-800', 'text-white');
            document.getElementById('btn-mode-2p').classList.replace('border-indigo-400', 'border-transparent');
            document.getElementById('btn-mode-2p').classList.replace('bg-indigo-600', 'bg-gray-200');
            document.getElementById('btn-mode-2p').classList.replace('text-white', 'text-gray-800');
            // Show speed buttons, reset to Normal
            state.game.speedMultiplier = 1;
            document.getElementById('btn-speed-normal').className = 'flex-1 bg-green-600 text-white font-bold py-3 rounded-xl border-4 border-green-400 transform transition text-xl';
            document.getElementById('btn-speed-chill').className = 'flex-1 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200 font-bold py-3 rounded-xl border-4 border-transparent transform transition text-xl';
        });

        document.getElementById('btn-mode-2p').addEventListener('click', () => {
            state.session.numPlayers = 2; state.game.players[1].active = true;
            document.getElementById('p2-name-input-wrap').classList.remove('hidden');
            document.getElementById('player2-name').focus();
            document.getElementById('btn-mode-2p').classList.replace('border-transparent', 'border-indigo-400');
            document.getElementById('btn-mode-2p').classList.replace('bg-gray-200', 'bg-indigo-600');
            document.getElementById('btn-mode-2p').classList.replace('text-gray-800', 'text-white');
            document.getElementById('btn-mode-1p').classList.replace('border-indigo-400', 'border-transparent');
            document.getElementById('btn-mode-1p').classList.replace('bg-indigo-600', 'bg-gray-200');
            document.getElementById('btn-mode-1p').classList.replace('text-white', 'text-gray-800');
            // Show speed buttons, reset to Normal
            state.game.speedMultiplier = 1;
            document.getElementById('btn-speed-normal').className = 'flex-1 bg-green-600 text-white font-bold py-3 rounded-xl border-4 border-green-400 transform transition text-xl';
            document.getElementById('btn-speed-chill').className = 'flex-1 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200 font-bold py-3 rounded-xl border-4 border-transparent transform transition text-xl';
        });

        document.getElementById('btn-speed-normal').addEventListener('click', () => {
            state.game.speedMultiplier = 1;
            document.getElementById('btn-speed-normal').className = 'flex-1 bg-green-600 text-white font-bold py-3 rounded-xl border-4 border-green-400 transform transition text-xl';
            document.getElementById('btn-speed-chill').className = 'flex-1 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200 font-bold py-3 rounded-xl border-4 border-transparent transform transition text-xl';
            if (document.getElementById('lb-mode-label')) document.getElementById('lb-mode-label').innerText = 'Normal';
            app.leaderboards.renderLeaderboard();
        });

        document.getElementById('btn-speed-chill').addEventListener('click', () => {
            state.game.speedMultiplier = 0.4;
            document.getElementById('btn-speed-chill').className = 'flex-1 bg-cyan-600 text-white font-bold py-3 rounded-xl border-4 border-cyan-400 transform transition text-xl';
            document.getElementById('btn-speed-normal').className = 'flex-1 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200 font-bold py-3 rounded-xl border-4 border-transparent transform transition text-xl';
            if (document.getElementById('lb-mode-label')) document.getElementById('lb-mode-label').innerText = 'Chill';
            app.leaderboards.renderLeaderboard();
        });

        document.getElementById('btn-continue').addEventListener('click', () => {
            const name = document.getElementById('player-name').value.trim();
            if (!name) {
                const lang = document.getElementById('lang-select').value;
                alert(lang === 'mi' ? 'Kuhuna tō ingoa koa.' : 'Please enter your name.');
                return;
            }
            state.session.currentPlayerName = name;
            localStorage.setItem('player_name', name);

            const streak = app.progress.calculateStreak();
            app.streak.renderStreak(streak);

            // Show streak screen
            document.getElementById('login-screen-wrap').classList.add('hidden');
            document.getElementById('streak-screen').classList.remove('hidden');
            state.game.gameState = 'dashboard';
            if (streak >= 3 && typeof startFireworks === 'function') startFireworks();
        });

        // ── Back button navigation ──
        document.getElementById('btn-streak-back').addEventListener('click', () => {
            document.getElementById('streak-screen').classList.add('hidden');
            document.getElementById('login-screen-wrap').classList.remove('hidden');
            if (typeof stopFireworks === 'function') stopFireworks();
        });

        document.getElementById('btn-dashboard-back').addEventListener('click', () => {
            document.getElementById('dashboard-screen').classList.add('hidden');
            document.getElementById('login-screen-wrap').classList.remove('hidden');
        });

        document.getElementById('btn-warning-back').addEventListener('click', () => {
            app.warning.stopWarningAudio();
            document.getElementById('warning-screen').classList.add('hidden');
            document.getElementById('dashboard-screen').classList.remove('hidden');
        });

        document.getElementById('btn-start-back').addEventListener('click', () => {
            document.getElementById('start-screen').classList.add('hidden');
            document.getElementById('dashboard-screen').classList.remove('hidden');
        });

        document.getElementById('btn-calibration-back').addEventListener('click', () => {
            clearTimeout(calibrationTimeout);
            state.game.gameState = 'loading';
            document.getElementById('calibration-screen').classList.add('hidden');
            document.getElementById('start-screen').classList.remove('hidden');
        });

        document.getElementById('btn-streak-next').addEventListener('click', () => {
            document.getElementById('streak-screen').classList.add('hidden');
            document.getElementById('dashboard-screen').classList.remove('hidden');
            if (typeof stopFireworks === 'function') stopFireworks();
            app.localization.updateLanguage(document.getElementById('lang-select').value);
            app.leaderboards.renderLeaderboard();
        });

        document.getElementById('btn-play').addEventListener('click', () => {
            // Read P2 name if in 2P mode
            if (state.session.numPlayers === 2) {
                const p2name = document.getElementById('player2-name').value.trim();
                if (!p2name) {
                    alert('Please enter Player 2\'s name.');
                    document.getElementById('player2-name').focus();
                    return;
                }
                state.session.currentPlayer2Name = p2name;
                localStorage.setItem('player2_name', p2name);
            }
            document.getElementById('dashboard-screen').classList.add('hidden');
            document.getElementById('loading-screen').classList.remove('hidden');
            state.game.gameState = 'loading';
            app.camera.initCameraSequence();
        });

        document.getElementById('warning-continue-btn').addEventListener('click', () => {
            app.warning.stopWarningAudio();
            document.getElementById('warning-screen').classList.add('hidden');
            app.tutorial.showInstructionsScreen();
        });

        document.getElementById('warning-read-btn').addEventListener('click', app.warning.toggleWarningRead);

        document.getElementById('instruction-advance').addEventListener('click', app.tutorial.advanceInstruction);
        document.getElementById('instruction-next').addEventListener('click', (e) => { e.stopPropagation(); app.tutorial.advanceInstruction(); });
        document.getElementById('instruction-prev').addEventListener('click', (e) => { e.stopPropagation(); app.tutorial.goBackInstruction(); });
        document.getElementById('instruction-skip').addEventListener('click', (e) => { e.stopPropagation(); app.tutorial.skipInstructions(); });
        document.getElementById('instruction-mute').addEventListener('click', (e) => { e.stopPropagation(); app.tutorial.toggleInstructionMute(); });

        document.getElementById('start-btn').addEventListener('click', () => {
            app.audio.audioCtx.resume();
            app.audio.bgMusic.play().then(() => { app.audio.bgMusic.pause(); app.audio.bgMusic.currentTime = 0; }).catch(e => console.log(e));
            document.getElementById('start-screen').classList.add('hidden');
            startCalibration();
        });

        document.getElementById('btn-recalibrate-players').addEventListener('click', () => {
            if (state.game.gameState !== 'playing') return;
            app.audio.bgMusic.pause();
            app.notifications.clearOrbNotify();
            app.feedback.hideShieldActive();
            app.feedback.hideLevelUp();
            document.getElementById('hud-1p').classList.add('hidden');
            document.getElementById('hud-2p').classList.add('hidden');
            if (state.game.gameLoopId) cancelAnimationFrame(state.game.gameLoopId);
            startCalibration();
        });

        document.getElementById('restart-btn').addEventListener('click', () => {
            app.finishPhoto.resetFinishPhoto();
            document.getElementById('game-over-screen').classList.remove('mode-2p');
            document.getElementById('game-over-screen').classList.add('hidden');
            document.getElementById('winner-stamp-p1').classList.remove('show');
            document.getElementById('winner-stamp-p2').classList.remove('show');
            document.getElementById('dashboard-screen').classList.remove('hidden');
            document.getElementById('shield-active-hud').classList.add('hidden');
            app.camera.videoElement.classList.add('hidden');
            app.camera.camSingle.classList.add('hidden');
            document.getElementById('split-cam-container').style.display = 'none';
            // Close leaderboard modal if open
            const lbModal = document.getElementById('lb-modal');
            if (lbModal) lbModal.style.display = 'none';
            document.getElementById('gameover-lb-wrap').classList.add('hidden');
            document.getElementById('btn-gameover-lb').textContent = '🏆 Leaderboard';
            if (document.getElementById('winner-banner')) document.getElementById('winner-banner').classList.add('hidden');
            if (document.getElementById('final-p2-score-container')) document.getElementById('final-p2-score-container').classList.add('hidden');
            state.game.gameState = 'dashboard';
            app.world.drawStaticBackground();
            app.leaderboards.renderLeaderboard();
        });

        document.getElementById('btn-play-again').addEventListener('click', () => {
            app.finishPhoto.resetFinishPhoto();
            // Reset game-over screen state
            document.getElementById('game-over-screen').classList.remove('mode-2p');
            document.getElementById('game-over-screen').classList.add('hidden');
            document.getElementById('winner-stamp-p1').classList.remove('show');
            document.getElementById('winner-stamp-p2').classList.remove('show');
            if (document.getElementById('winner-banner')) document.getElementById('winner-banner').classList.add('hidden');
            document.getElementById('gameover-lb-wrap').classList.add('hidden');
            document.getElementById('shield-active-hud').classList.add('hidden');
            // Jump straight to calibration — skip warning & tutorial
            app.audio.audioCtx.resume();
            startCalibration();
        });
    }


    return { bind };
}

// Source: src/rendering/world.js
/** world: see docs/architecture.md for ownership and compatibility rules. */
function createWorld({ state, app }) {
    const { ctx } = app.viewport;

    const horizonY = state.viewport.gameHeight * 0.3;

    function getScreenPos(laneIdx, depth, canvasW) {
        const laneWidthBottom = canvasW / 3;
        const laneWidthTop = canvasW / 8;
        const currentY = horizonY + (state.viewport.gameHeight - horizonY) * depth;
        const totalWidthAtDepth = laneWidthTop + (laneWidthBottom * 3 - laneWidthTop) * depth;
        const laneW = totalWidthAtDepth / 3;
        const centerX = canvasW / 2;
        return { x: centerX + (laneIdx * laneW), y: currentY, w: laneW * 0.8 };
    }

    function prepareParticles(canvasW, isDark) {
        // Shooting stars — rate and colour change with style
        const spawnRate = state.game.skyStyle >= 3 ? 0.04 : state.game.skyStyle >= 1 ? 0.025 : 0.015;
        if (Math.random() < spawnRate) {
            const hue = state.game.skyStyle >= 2 ? Math.floor(Math.random() * 360) : null;
            state.game.skyParticles.push({
                x:    Math.random() * canvasW * 0.65,
                y:    Math.random() * horizonY * 0.5,
                vx:   9 + Math.random() * 8,
                vy:   2 + Math.random() * 3,
                life: 1.0,
                len:  90 + Math.random() * 80,   // longer tail (was 55–120)
                lw:   state.game.skyStyle >= 3 ? 4 : 3,
                color: hue !== null
                    ? `hsla(${hue},100%,${isDark ? 90 : 97}%,`
                    : (isDark ? 'rgba(220,235,255,' : 'rgba(255,255,255,')
            });
        }

        state.game.skyParticles = state.game.skyParticles.filter(p => p.life > 0);
    }

    function advanceBackground(canvasW) {
        if (!state.game.skyEffectsEnabled) return;
        state.game.skyStarBase.forEach(s => { s.twinkle += 0.055; });
        prepareParticles(canvasW, document.documentElement.classList.contains('dark'));
        state.game.skyParticles.forEach(p => {
            p.x += p.vx; p.y += p.vy;
            p.life -= 0.016;
        });
    }

    function drawBackground(canvasW) {
        const isDark = document.documentElement.classList.contains('dark');
        ctx.fillStyle = isDark ? '#0f172a' : '#bae6fd'; ctx.fillRect(0, 0, canvasW, horizonY);
        ctx.fillStyle = isDark ? '#1e293b' : '#bbf7d0'; ctx.fillRect(0, horizonY, canvasW, state.viewport.gameHeight - horizonY);

        // ── Sky visual effects (active from game start, style upgrades every 100 pts) ──
        if (state.game.skyEffectsEnabled) {
            // Style 1+: Flowing aurora bands
            if (state.game.skyStyle >= 1) {
                const aurCols = isDark
                    ? ['rgba(42,157,143,', 'rgba(99,102,241,', 'rgba(139,92,246,']
                    : ['rgba(80,200,170,',  'rgba(130,160,255,', 'rgba(190,140,255,'];
                const bandCount = state.game.skyStyle >= 3 ? 4 : 3;
                for (let b = 0; b < bandCount; b++) {
                    const baseY = horizonY * (0.15 + b * 0.18);
                    const t2 = state.game.frameCount * 0.012 + b * 1.8;
                    const opacity = (0.12 + Math.sin(state.game.frameCount * 0.018 + b) * 0.07) * (state.game.skyStyle >= 3 ? 1.5 : 1);
                    ctx.beginPath();
                    for (let x = 0; x <= canvasW; x += 20) {
                        const y = baseY + Math.sin(x * 0.007 + t2) * 14 + Math.sin(x * 0.014 + t2 * 1.4) * 7;
                        x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
                    }
                    ctx.strokeStyle = aurCols[b % aurCols.length] + opacity + ')';
                    ctx.lineWidth = 10 + state.game.skyStyle * 2;
                    ctx.stroke();
                }
            }

            // Twinkling stars — colorful from style 2+
            state.game.skyStarBase.forEach(s => {
                s.twinkle += 0.055;
                const alpha = 0.55 + Math.sin(s.twinkle) * 0.45; // 0.1–1.0
                const sx = s.x * canvasW / state.viewport.gameWidth;
                const radius = s.r * 1.8 * (state.game.skyStyle >= 3 ? 1.5 : 1);
                const hueVal = (s.hue + state.game.frameCount * 0.3) % 360;
                const col = state.game.skyStyle >= 2
                    ? `hsla(${hueVal},100%,${isDark ? 92 : 97}%,${Math.max(0, alpha)})`
                    : isDark ? `rgba(255,255,220,${Math.max(0, alpha)})` : `rgba(255,255,255,${Math.max(0, alpha)})`;
                // Fake glow: outer soft halo (no shadowBlur — much cheaper)
                ctx.beginPath();
                ctx.arc(sx, s.y, radius * 3, 0, Math.PI * 2);
                ctx.fillStyle = state.game.skyStyle >= 2
                    ? `hsla(${hueVal},100%,80%,${Math.max(0, alpha * 0.18)})`
                    : isDark ? `rgba(200,230,255,${Math.max(0, alpha * 0.18)})` : `rgba(255,255,255,${Math.max(0, alpha * 0.15)})`;
                ctx.fill();
                // Core star
                ctx.beginPath();
                ctx.arc(sx, s.y, radius, 0, Math.PI * 2);
                ctx.fillStyle = col;
                ctx.fill();
            });

            prepareParticles(canvasW, isDark);
            state.game.skyParticles.forEach(p => {
                ctx.save();
                ctx.globalAlpha = p.life;
                const tailLen = p.len * p.life;
                const mag = Math.hypot(p.vx, p.vy);
                // Bright core dot at head (no shadowBlur — use double circle fake glow)
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.lw * 2.5, 0, Math.PI * 2);
                ctx.fillStyle = p.color + '0.25)';
                ctx.fill();
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.lw * 1.2, 0, Math.PI * 2);
                ctx.fillStyle = p.color + '1)';
                ctx.fill();
                // Fading tail
                const grad = ctx.createLinearGradient(
                    p.x, p.y,
                    p.x - p.vx / mag * tailLen, p.y - p.vy / mag * tailLen
                );
                grad.addColorStop(0, p.color + '1)');
                grad.addColorStop(1, p.color + '0)');
                ctx.strokeStyle = grad;
                ctx.lineWidth = p.lw;
                ctx.lineCap = 'round';
                ctx.beginPath();
                ctx.moveTo(p.x, p.y);
                ctx.lineTo(p.x - p.vx / mag * tailLen, p.y - p.vy / mag * tailLen);
                ctx.stroke();
                ctx.restore();
                p.x += p.vx; p.y += p.vy;
                p.life -= 0.016;
            });
        }

        ctx.strokeStyle = isDark ? '#334155' : '#ffffff'; ctx.lineWidth = 6;

        const pFarLeft = getScreenPos(-1.5, 0, canvasW), pFarRight = getScreenPos(1.5, 0, canvasW);
        const pNearLeft = getScreenPos(-1.5, 1, canvasW), pNearRight = getScreenPos(1.5, 1, canvasW);
        const pFarL1 = getScreenPos(-0.5, 0, canvasW), pNearL1 = getScreenPos(-0.5, 1, canvasW);
        const pFarR1 = getScreenPos(0.5, 0, canvasW), pNearR1 = getScreenPos(0.5, 1, canvasW);

        ctx.beginPath();
        ctx.moveTo(pNearLeft.x, pNearLeft.y); ctx.lineTo(pFarLeft.x, pFarLeft.y);
        ctx.moveTo(pNearL1.x, pNearL1.y); ctx.lineTo(pFarL1.x, pFarL1.y);
        ctx.moveTo(pNearR1.x, pNearR1.y); ctx.lineTo(pFarR1.x, pFarR1.y);
        ctx.moveTo(pNearRight.x, pNearRight.y); ctx.lineTo(pFarRight.x, pFarRight.y);
        ctx.stroke();
    }

    function drawStaticBackground() {
        ctx.clearRect(0, 0, state.viewport.gameWidth, state.viewport.gameHeight);
        // bg-canvas provides the animated background during non-game states
    }

    return { horizonY, getScreenPos, drawBackground, advanceBackground, drawStaticBackground };
}

// Source: src/rendering/entities.js
/** entities: see docs/architecture.md for ownership and compatibility rules. */
function createEntities({ state, app }) {
    const { ctx } = app.viewport;

    function drawOrb(orb, subW) {
        const oPos = app.world.getScreenPos(orb.lane, orb.depth, subW);
        const scale = 0.2 + (orb.depth * 0.8);
        const radius = 42 * scale;   // was 22 — now much bigger
        const bobY = Math.sin(state.game.frameCount * 0.08 + orb.bobOffset) * 10 * scale;
        const pulse = 1 + Math.sin(state.game.frameCount * 0.12 + orb.bobOffset) * 0.12; // gentle pulse

        ctx.save();
        ctx.shadowBlur = 45 * scale;  // stronger glow

        if (orb.type === 'shield') {
            ctx.shadowColor = '#06b6d4';

            // Outer pulse ring
            ctx.beginPath();
            ctx.arc(oPos.x, oPos.y + bobY, radius * 1.5 * pulse, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(6,182,212,0.25)';
            ctx.lineWidth = 5 * scale;
            ctx.stroke();

            // Main orb
            const grad = ctx.createRadialGradient(oPos.x, oPos.y + bobY - radius * 0.3, radius * 0.1, oPos.x, oPos.y + bobY, radius);
            grad.addColorStop(0, '#ffffff');
            grad.addColorStop(0.4, '#67e8f9');
            grad.addColorStop(1, '#0891b2');
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(oPos.x, oPos.y + bobY, radius, 0, Math.PI * 2);
            ctx.fill();

            // Shield icon — much larger
            ctx.fillStyle = '#ffffff';
            ctx.shadowBlur = 0;
            ctx.font = `bold ${Math.floor(radius * 1.3)}px Arial`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('🛡️', oPos.x, oPos.y + bobY);

        } else {
            ctx.shadowColor = '#ec4899';

            // Outer pulse ring
            ctx.beginPath();
            ctx.arc(oPos.x, oPos.y + bobY, radius * 1.5 * pulse, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(236,72,153,0.25)';
            ctx.lineWidth = 5 * scale;
            ctx.stroke();

            // Main orb
            const grad = ctx.createRadialGradient(oPos.x, oPos.y + bobY - radius * 0.3, radius * 0.1, oPos.x, oPos.y + bobY, radius);
            grad.addColorStop(0, '#ffffff');
            grad.addColorStop(0.4, '#f9a8d4');
            grad.addColorStop(1, '#be185d');
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(oPos.x, oPos.y + bobY, radius, 0, Math.PI * 2);
            ctx.fill();

            // Heart icon — much larger
            ctx.fillStyle = '#ffffff';
            ctx.shadowBlur = 0;
            ctx.font = `bold ${Math.floor(radius * 1.3)}px Arial`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('💗', oPos.x, oPos.y + bobY);
        }
        ctx.restore();
    }

    function drawObstacle(obs, subW) {
        const oPos = app.world.getScreenPos(obs.lane, obs.depth, subW);
        const scale = 0.2 + (obs.depth * 0.8);
        const totalW = oPos.w * obs.span * scale;

        ctx.save();
        if (obs.type === 'high') {
            ctx.fillStyle = '#f59e0b'; ctx.shadowColor = '#f59e0b'; ctx.shadowBlur = 15;
            ctx.fillRect(oPos.x - (totalW/2), oPos.y - (100*scale), totalW, 40*scale);
        } else if (obs.type === 'low' || obs.type === 'low-wide') {
            ctx.fillStyle = obs.type === 'low-wide' ? '#dc2626' : '#ef4444'; ctx.shadowColor = ctx.fillStyle; ctx.shadowBlur = 15;
            ctx.fillRect(oPos.x - (totalW/2), oPos.y - (30*scale), totalW, 30*scale);
        } else if (obs.type === 'block') {
            ctx.fillStyle = '#ec4899'; ctx.shadowColor = '#ec4899'; ctx.shadowBlur = 15;
            ctx.fillRect(oPos.x - (totalW/2), oPos.y - (80*scale), totalW, 80*scale);
        } else if (obs.type === 'door') {
            ctx.fillStyle = '#0ea5e9'; ctx.shadowColor = '#0ea5e9'; ctx.shadowBlur = 15;
            ctx.fillRect(oPos.x - (totalW/2), oPos.y - (120*scale), totalW, 40*scale);
            ctx.fillRect(oPos.x - (totalW/2), oPos.y - (120*scale), 20*scale, 120*scale);
            ctx.fillRect(oPos.x + (totalW/2) - (20*scale), oPos.y - (120*scale), 20*scale, 120*scale);
        }
        ctx.restore();
    }

    // Draw shield ring around player when shield is active
    function drawShieldRing(p, subW) {
        if (!p.shieldActive) return;
        const basePos  = app.world.getScreenPos(p.lane, 0.85, subW);
        const pulse    = 1 + Math.sin(state.game.frameCount * 0.15) * 0.08;
        const radius   = 80;
        const progress = p.shieldTimer / 300;   // countdown 1 → 0
        const secsLeft = Math.ceil(p.shieldTimer / 60);

        ctx.save();

        // Filled semi-transparent inner glow
        ctx.beginPath();
        ctx.arc(p.renderX || basePos.x, basePos.y - 35, radius * pulse, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(6,182,212,0.08)';
        ctx.fill();

        // Background ring (faint)
        ctx.beginPath();
        ctx.arc(p.renderX || basePos.x, basePos.y - 35, radius * pulse, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(6,182,212,0.2)';
        ctx.lineWidth = 10;
        ctx.stroke();

        // Countdown arc — drains as time passes
        ctx.beginPath();
        ctx.arc(p.renderX || basePos.x, basePos.y - 35, radius * pulse,
            -Math.PI / 2, -Math.PI / 2 + (Math.PI * 2 * progress));
        ctx.strokeStyle = secsLeft <= 5 ? '#fbbf24' : '#06b6d4';
        ctx.lineWidth = 10;
        ctx.shadowColor = ctx.strokeStyle;
        ctx.shadowBlur = 30;
        ctx.stroke();

        // Countdown text above player
        ctx.fillStyle = secsLeft <= 5 ? '#fbbf24' : '#06b6d4';
        ctx.shadowBlur = 8;
        ctx.font = 'bold 22px Segoe UI';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'bottom';
        ctx.fillText(`🛡️ ${secsLeft}s`, p.renderX || basePos.x, basePos.y - 35 - radius * pulse - 6);

        ctx.restore();
    }

    function updateAndDrawPlayer(p, subW, playerIndex, paint = true) {
        const basePos = app.world.getScreenPos(p.lane, 0.85, subW);

        if (p.renderX === undefined) p.renderX = basePos.x;
        p.renderX += (basePos.x - p.renderX) * 0.2;

        const dx = basePos.x - p.renderX;
        p.renderAngle = dx * 0.005;

        const isMovingLeft = dx < -2;
        const isMovingRight = dx > 2;

        let targetArmL = Math.PI * 0.5 + Math.sin(state.game.frameCount * 0.2) * 0.2;
        let targetArmR = Math.PI * 0.5 - Math.sin(state.game.frameCount * 0.2) * 0.2;
        let targetYOffset = 0;
        let targetScaleY = 1;
        let targetScaleX = 1;

        if (p.isResting) {
            // Arms crossed visual: arms point inward
            targetArmL = Math.PI * 0.1;   // Right-ish
            targetArmR = Math.PI * 0.9;   // Left-ish
            targetYOffset = 0;
            targetScaleY = 0.95;
            targetScaleX = 1.05;
        } else if (p.isJumping) {
            targetYOffset = -90;
            targetScaleY = 1.1;
            targetScaleX = 0.9;
            targetArmL = Math.PI * 1.4;
            targetArmR = -Math.PI * 0.4;
        } else if (p.isSquatting) {
            targetYOffset = 0;
            targetScaleY = 0.6;
            targetScaleX = 1.3;
            targetArmL = Math.PI;
            targetArmR = 0;
        } else {
            targetYOffset = Math.sin(state.game.frameCount * 0.3) * 5;
            if (isMovingLeft) targetArmL = Math.PI;
            else if (isMovingRight) targetArmR = 0;
        }

        if (p.renderArmL === undefined) p.renderArmL = targetArmL;
        if (p.renderArmR === undefined) p.renderArmR = targetArmR;

        p.renderYOffset += (targetYOffset - p.renderYOffset) * 0.3;
        p.renderScaleY += (targetScaleY - p.renderScaleY) * 0.3;
        p.renderScaleX += (targetScaleX - p.renderScaleX) * 0.3;
        p.renderArmL += (targetArmL - p.renderArmL) * 0.3;
        p.renderArmR += (targetArmR - p.renderArmR) * 0.3;

        // Consume the original jump random value even on an unpainted step.
        const flameHeight = p.isJumping ? 42 + Math.random() * 28 : 0;
        if (!paint) return;

        // Draw shield ring behind player
        drawShieldRing(p, subW);

        ctx.save();
        ctx.translate(p.renderX, basePos.y + p.renderYOffset);
        ctx.rotate(p.renderAngle);
        ctx.scale(p.renderScaleX, p.renderScaleY);

        let color = playerIndex === 0 ? '#3b82f6' : '#ef4444';
        if (p.shieldActive) color = '#06b6d4'; // Cyan tint while shielded
        else if (p.isJumping) color = playerIndex === 0 ? '#60a5fa' : '#f87171';
        else if (p.isSquatting) color = playerIndex === 0 ? '#1e3a8a' : '#7f1d1d';
        else if (p.isResting) color = '#a78bfa'; // Purple tint while resting
        if (p.invulnerableFrames > 0 && !p.shieldActive) color = '#ffffff';

        const w = 70, h = 70;

        if (p.isJumping) {
            ctx.fillStyle = '#fb923c';
            ctx.beginPath();
            ctx.moveTo(-w/3, 0);
            ctx.lineTo(0, flameHeight);
            ctx.lineTo(w/3, 0);
            ctx.fill();
        }

        ctx.fillStyle = color;
        const armLength = 42;
        const armThickness = 17;
        const shoulderY = -h + 21;

        ctx.save();
        ctx.translate(-w/2, shoulderY);
        ctx.rotate(p.renderArmL);
        ctx.beginPath();
        ctx.roundRect(0, -armThickness/2, armLength, armThickness, armThickness/2);
        ctx.fill();
        ctx.restore();

        ctx.save();
        ctx.translate(w/2, shoulderY);
        ctx.rotate(p.renderArmR);
        ctx.beginPath();
        ctx.roundRect(0, -armThickness/2, armLength, armThickness, armThickness/2);
        ctx.fill();
        ctx.restore();

        ctx.shadowColor = p.shieldActive ? '#06b6d4' : color;
        ctx.shadowBlur = p.shieldActive ? 25 : 15;
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.roundRect(-w/2, -h, w, h, 12);
        ctx.fill();

        ctx.fillStyle = '#ffffff';
        ctx.shadowBlur = 0;
        ctx.beginPath();
        ctx.roundRect(-w/2 + 8, -h + 10, w - 16, 15, 6);
        ctx.fill();

        ctx.restore();

        ctx.fillStyle = 'rgba(0,0,0,0.5)'; ctx.shadowBlur = 0;
        ctx.beginPath();
        ctx.ellipse(p.renderX, basePos.y, 35 * p.renderScaleX, 11, 0, 0, Math.PI * 2);
        ctx.fill();
    }

    return { drawOrb, drawObstacle, drawShieldRing, updateAndDrawPlayer };
}

// Source: src/ui/hud.js
/** hud: see docs/architecture.md for ownership and compatibility rules. */
function createHud({ state, app }) {
    function layoutGameplayNotices() {
        if (state.game.gameState !== 'playing') return;
        const notices = ['player-tracking-notice', 'orb-notify'].map(id => document.getElementById(id))
            .filter(element => !element.hidden && !element.classList.contains('hidden'));
        if (!notices.length) return;
        const container = document.getElementById('game-container').getBoundingClientRect();
        const hud = document.getElementById(state.session.numPlayers === 1 ? 'hud-1p' : 'hud-2p').getBoundingClientRect();
        const gap = 12;
        let top = Math.max(gap, Math.ceil(hud.bottom - container.top) + gap);
        for (const notice of notices) {
            const maxHeight = Math.max(0, Math.floor(container.height - top - gap));
            const nextTop = `${top}px`, nextMaxHeight = `${maxHeight}px`;
            if (notice.style.top !== nextTop) notice.style.top = nextTop;
            if (notice.style.maxHeight !== nextMaxHeight) notice.style.maxHeight = nextMaxHeight;
            top += Math.ceil(notice.getBoundingClientRect().height) + gap;
        }
    }

    function renderRanking(id, playerIndex, dict) {
        const tile = document.getElementById(id);
        tile.querySelector('[data-ranking-label]').textContent = dict.hudLiveRanking;
        const ranking = app.scores.getLiveRanking(playerIndex);
        for (const [index, row] of [...tile.querySelectorAll('[data-rank-row]')].entries()) {
            const entry = ranking.rows[index];
            row.hidden = !entry;
            row.classList.toggle('hud-rank-current', !!entry && entry.playerIndex === playerIndex);
            row.querySelector('.hud-rank-number').textContent = entry ? `#${entry.rank}` : '';
            const name = row.querySelector('.hud-rank-name');
            const medal = entry && ['🥇 ', '🥈 ', '🥉 '][entry.rank - 1] || '';
            name.textContent = entry ? medal + entry.name : '';
            name.title = entry ? entry.name : '';
            row.querySelector('.hud-rank-score').textContent = entry ? entry.score : '';
        }
    }

    function renderPlayerName(id, name) {
        const element = document.getElementById(id);
        element.textContent = name;
        element.title = name;
    }

    function updateHUD() {
        const dict = app.localization.translations[document.getElementById('lang-select').value];
        if (state.session.numPlayers === 1) {
            document.getElementById('score-display-1p').innerText = Math.floor(state.game.score);
            document.getElementById('lives-display-1p').innerText = state.game.players[0].lives;
            document.getElementById('shield-display-1p').innerText = state.game.players[0].shieldOrbs;
            renderRanking('hud-ranking-1p', 0, dict);
        } else {
            // Both players share same score (co-op style)
            document.getElementById('score-display-2p').innerText = Math.floor(state.game.score);
            document.getElementById('score-display-2p-p2').innerText = Math.floor(state.game.score);
            // P1 (left board = hud-p2 elements) — person standing LEFT side of room
            document.getElementById('p2-lives-display').innerText = state.game.players[0].lives;
            document.getElementById('p2-shields').innerText = state.game.players[0].shieldOrbs;
            document.getElementById('score-display-2p-p2').innerText = Math.floor(state.game.players[0].score || state.game.score);
            renderPlayerName('p2-hud-name', state.session.currentPlayerName);
            // P2 (right board = hud-p1 elements) — person standing RIGHT side of room
            document.getElementById('p1-lives-display').innerText = state.game.players[1].lives;
            document.getElementById('p1-shields').innerText = state.game.players[1].shieldOrbs;
            document.getElementById('score-display-2p').innerText = Math.floor(state.game.players[1].score || state.game.score);
            renderPlayerName('p1-hud-name', state.session.currentPlayer2Name);
        }
        document.getElementById('energy-estimate-help').textContent = dict.energyEstimateHelp;
        document.querySelectorAll('[data-energy-estimate]').forEach(element => {
            element.title = dict.energyEstimateHelp;
        });
        layoutGameplayNotices();
    }

    window.addEventListener('resize', layoutGameplayNotices);

    return { updateHUD, layoutGameplayNotices };
}

// Source: src/ui/finish-photo.js
/** Frozen result photo presentation; camera inference and game rules stay elsewhere. */
function createFinishPhoto({ state, app }) {
    const layout = document.getElementById('game-over-layout');
    const stats = document.getElementById('game-over-screen');
    const single = document.getElementById('finish-photo-single');
    const dialog = document.getElementById('finish-photo-dialog');
    const closeButton = document.getElementById('finish-photo-close');
    const canvases = [document.getElementById('finish-photo-single-canvas'), document.getElementById('finish-photo-dual-canvas')];
    const exposureGain = 2 ** 0.7;
    // Apply photographic exposure in linear light, then return to sRGB.
    const exposureLut = Uint8ClampedArray.from({ length: 256 }, (_, value) => {
        const srgb = value / 255;
        const linear = (srgb <= 0.04045 ? srgb / 12.92 : ((srgb + 0.055) / 1.055) ** 2.4) * exposureGain;
        const exposed = linear <= 0.0031308 ? linear * 12.92 : 1.055 * linear ** (1 / 2.4) - 0.055;
        return Math.round(Math.min(1, exposed) * 255);
    });
    let anchors = [];

    function exposeCameraFrame(ctx, width, height) {
        const frame = ctx.getImageData(0, 0, width, height);
        for (let index = 0; index < frame.data.length; index += 4) {
            frame.data[index] = exposureLut[frame.data[index]];
            frame.data[index + 1] = exposureLut[frame.data[index + 1]];
            frame.data[index + 2] = exposureLut[frame.data[index + 2]];
        }
        ctx.putImageData(frame, 0, 0);
    }

    function observeFinishPlayers(poses) {
        if (state.game.gameState !== 'playing') return;
        anchors = poses.map(pose => {
            const valid = point => point && Number.isFinite(point.x) && Number.isFinite(point.y)
                && (point.visibility ?? 1) >= 0.6 && (point.presence ?? 1) >= 0.6;
            if (!pose || ![11, 12, 23, 24].every(id => valid(pose[id]))) return null;
            const shoulderX = (pose[11].x + pose[12].x) / 2;
            const shoulderY = (pose[11].y + pose[12].y) / 2;
            const torso = Math.abs((pose[23].y + pose[24].y) / 2 - shoulderY);
            const face = [0, 2, 5].map(id => pose[id]).filter(valid);
            return { x: face.length ? face.reduce((sum, p) => sum + p.x, 0) / face.length : shoulderX,
                y: face.length ? Math.min(...face.map(p => p.y)) - torso * 0.18 : shoulderY - torso * 0.5,
                width: Math.max(0.06, Math.min(0.2, Math.abs(pose[11].x - pose[12].x) * 0.75)), at: performance.now() };
        });
    }

    function drawCrown(ctx, anchor, width, height) {
        const size = width * anchor.width;
        const x = Math.max(size / 2, Math.min(width - size / 2, (1 - anchor.x) * width));
        const y = Math.max(size * 0.65, Math.min(height - 8, anchor.y * height));
        ctx.save();
        ctx.translate(x - size / 2, y - size * 0.6);
        ctx.scale(size, size);
        ctx.shadowColor = '#422006'; ctx.shadowBlur = 5;
        ctx.fillStyle = '#facc15'; ctx.strokeStyle = '#854d0e'; ctx.lineWidth = 0.035;
        ctx.beginPath(); ctx.moveTo(0.1, 0.55); ctx.lineTo(0, 0.06); ctx.lineTo(0.28, 0.28);
        ctx.lineTo(0.5, 0); ctx.lineTo(0.72, 0.28); ctx.lineTo(1, 0.06); ctx.lineTo(0.9, 0.55);
        ctx.closePath(); ctx.fill(); ctx.stroke();
        ctx.shadowBlur = 0; ctx.fillStyle = '#f59e0b'; ctx.fillRect(0.1, 0.45, 0.8, 0.12);
        ctx.fillStyle = '#ef4444'; ctx.beginPath(); ctx.arc(0.5, 0.38, 0.06, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
    }

    function closeFinishPhoto() {
        if (!dialog.open) return;
        dialog.close();
        if (state.game.gameState === 'gameover') {
            stats.classList.remove('hidden');
            document.getElementById('restart-btn').focus({ preventScroll: true });
        }
        canvases[1].width = canvases[1].height = 0;
    }

    function resetFinishPhoto() {
        if (dialog.open) dialog.close();
        single.hidden = true;
        layout.classList.remove('has-finish-photo');
        anchors = [];
        for (const canvas of canvases) canvas.width = canvas.height = 0;
    }

    function showFinishPhoto(winnerIndex = null) {
        if (state.game.gameState !== 'gameover') return false;
        layout.classList.remove('hidden');
        const video = app.camera.videoElement;
        if (video.readyState < 2 || !video.videoWidth || !video.videoHeight || video.ended) return false;
        const dual = state.session.numPlayers === 2;
        const canvas = canvases[dual ? 1 : 0];
        // Bound memory while keeping the full camera frame and its aspect ratio.
        const scale = Math.min(1, 1280 / video.videoWidth, 1280 / video.videoHeight);
        const width = Math.round(video.videoWidth * scale);
        const height = Math.round(width * video.videoHeight / video.videoWidth);
        const footer = Math.max(140, Math.round(width * 0.24));
        const finishedAt = new Date();
        const dateStamp = [String(finishedAt.getDate()).padStart(2, '0'),
            String(finishedAt.getMonth() + 1).padStart(2, '0'), finishedAt.getFullYear()].join('/');
        canvas.width = width; canvas.height = height + footer;
        const ctx = canvas.getContext('2d');
        try {
            ctx.save(); ctx.translate(width, 0); ctx.scale(-1, 1);
            ctx.drawImage(video, 0, 0, width, height); ctx.restore();
            exposeCameraFrame(ctx, width, height);
            const anchor = anchors[winnerIndex];
            if (dual && anchor && performance.now() - anchor.at <= 500) drawCrown(ctx, anchor, width, height);
            ctx.fillStyle = '#172554'; ctx.fillRect(0, height, width, footer);
            ctx.fillStyle = '#ffffff'; ctx.textAlign = 'center';
            ctx.font = `900 ${Math.max(24, width * 0.065)}px system-ui, sans-serif`;
            ctx.fillText('ACTIVE RUNNER', width / 2, height + footer * 0.3, width - 24);
            const dict = app.localization.translations[document.getElementById('lang-select').value];
            const names = [state.session.currentPlayerName, state.session.currentPlayer2Name];
            const score = dual ? state.game.players[winnerIndex]?.score || 0 : state.game.score;
            const caption = dual ? `🏆 ${names[winnerIndex]} · ${dict.score} ${Math.floor(score)}` : `${names[0]} · ${dict.score} ${Math.floor(score)}`;
            ctx.font = `700 ${Math.max(22, width * 0.06)}px system-ui, sans-serif`;
            ctx.fillText(caption, width / 2, height + footer * 0.61, width - 24);
            ctx.fillStyle = '#c7d2fe';
            ctx.font = `700 ${Math.max(20, width * 0.045)}px system-ui, sans-serif`;
            ctx.fillText(dateStamp, width / 2, height + footer * 0.88, width - 24);
            canvas.setAttribute('aria-label', `Active Runner — ${caption} — ${dateStamp}`);
            closeButton.setAttribute('aria-label', dict.finishPhotoClose);
            document.getElementById('finish-photo-title').textContent = dict.finishPhotoTitle;
        } catch (error) {
            canvas.width = canvas.height = 0;
            app.debug.record('finish_photo.error', { message: String(error) });
            return false;
        }
        if (dual) {
            stats.classList.add('hidden');
            dialog.showModal();
            closeButton.focus();
        } else {
            single.hidden = false;
            layout.classList.add('has-finish-photo');
        }
        return true;
    }

    closeButton.addEventListener('click', closeFinishPhoto);
    dialog.addEventListener('cancel', event => { event.preventDefault(); closeFinishPhoto(); });
    return { observeFinishPlayers, showFinishPhoto, closeFinishPhoto, resetFinishPhoto };
}

// Source: src/game/session.js
/** session: see docs/architecture.md for ownership and compatibility rules. */
function createSession({ state, app }) {
    function startGameplay() {
        app.camera.invalidatePoseFrame();
        app.finishPhoto.resetFinishPhoto();
        app.trackingSafety.resetTrackingSafety();
        app.debug.record('game.start', { players: state.session.numPlayers, speedMultiplier: state.game.speedMultiplier,
            energy: app.energy.energyAssumptions() });
        app.notifications.clearOrbNotify();
        app.trackingStatus.clearTrackingStatus();
        document.getElementById('calibration-screen').classList.add('hidden');
        document.getElementById('shield-active-hud').classList.add('hidden');

        if (state.session.numPlayers === 1) {
            document.getElementById('hud-1p').classList.remove('hidden');
            document.getElementById('hud-2p').classList.add('hidden');
        } else {
            document.getElementById('hud-1p').classList.add('hidden');
            document.getElementById('hud-2p').classList.remove('hidden');
            document.getElementById('hud-p2').classList.remove('hidden');
            // p2-hud-name = LEFT board = players[0] = person entered first (P1 name)
            // p1-hud-name = RIGHT board = players[1] = person entered second (P2 name)
            document.getElementById('p2-hud-name').innerText = state.session.currentPlayerName;
            document.getElementById('p1-hud-name').innerText = state.session.currentPlayer2Name;
        }

        state.game.gameState = 'playing'; state.game.score = 0; state.game.speed = 4; state.game.frameCount = 0; state.game.obstacles = []; state.game.orbs = [];
        state.game.levelUpTimer = 0; state.game.nextMilestone = 100; state.game.streakBonusGranted = false; state.game.blockRestTimer = 0;
        state.game.skyStyle = 0; state.game.skyParticles = [];
        // Sky starts immediately with base style
        state.game.skyEffectsEnabled = true;
        state.game.skyStarBase = Array.from({ length: 28 }, () => ({
            x: Math.random() * state.viewport.gameWidth,
            y: Math.random() * app.world.horizonY * 0.88,
            r: 0.7 + Math.random() * 2,
            twinkle: Math.random() * Math.PI * 2,
            hue: Math.floor(Math.random() * 360)
        }));

        for (let i=0; i<state.session.numPlayers; i++) {
            app.laneGestures.resetLaneGestures(state.game.players[i]);
            state.game.players[i].lives = 3; state.game.players[i].lane = 0; state.game.players[i].stats = {squats: 0, jumps: 0}; state.game.players[i].score = 0;
            state.game.players[i].invulnerableFrames = 0;
            state.game.players[i].shieldOrbs = 0; state.game.players[i].shieldActive = false; state.game.players[i].shieldTimer = 0;
            state.game.players[i].isResting = false; state.game.players[i].armsCrossedNow = false; state.game.players[i].restingMode = false; state.game.players[i].restCooldown = 0; state.game.players[i].eliminated = false;
            state.game.players[i].renderX = undefined;
            state.game.players[i].renderYOffset = 0; state.game.players[i].renderScaleX = 1; state.game.players[i].renderScaleY = 1;
            state.game.players[i].renderAngle = 0; state.game.players[i].renderArmL = undefined; state.game.players[i].renderArmR = undefined;
        }

        // The daily bonus is earned by a real streak, once per local calendar day.
        const streak = Number(localStorage.getItem('current_streak')) || 0;
        const todayStr = app.progress.getLocalDateKey();
        const claimedDate = localStorage.getItem('streak_bonus_claimed_date');
        const loggedInToday = localStorage.getItem('last_login_date') === todayStr;
        document.getElementById('streak-bonus-banner').classList.add('hidden');

        // Grant shields
        if (loggedInToday && streak >= 3 && claimedDate !== todayStr) {
            for (let i = 0; i < state.session.numPlayers; i++) state.game.players[i].shieldOrbs = 5;
            localStorage.setItem('streak_bonus_claimed_date', todayStr);
            state.game.streakBonusGranted = true;
            document.getElementById('streak-reward-notice').classList.add('hidden');
        }
        if (state.game.streakBonusGranted) {
            document.getElementById('streak-bonus-text').textContent = `🔥 ${streak}-Day Login Streak  🛡️ +5 Shields!`;
            const banner = document.getElementById('streak-bonus-banner');
            banner.classList.remove('hidden');
            banner.style.animation = 'none';
            banner.offsetHeight;
            banner.style.animation = '';
            setTimeout(() => banner.classList.add('hidden'), 4500);
        }

        app.energy.resetEnergy();
        app.hud.updateHUD();
        app.camera.showCameraForMode();
        app.audio.bgMusic.currentTime = 0; app.audio.bgMusic.play().catch(e => console.log(e));
        if(state.game.gameLoopId) cancelAnimationFrame(state.game.gameLoopId);
        app.simulation.resetFrameClock();
        app.simulation.gameLoop();
    }

    function gameOver() {
        app.energy.stopEnergy();
        app.debug.record('game.over', { score: state.game.score });
        app.trackingSafety.resetTrackingSafety();
        state.game.gameState = 'gameover';
        app.notifications.clearOrbNotify();
        app.trackingStatus.clearTrackingStatus();
        app.audio.bgMusic.pause(); app.audio.playSynth('hit');
        app.scores.saveScore(state.game.score);
        app.leaderboards.renderGameOverLeaderboard();
        document.getElementById('shield-active-hud').classList.add('hidden');
        document.getElementById('hud-1p').classList.add('hidden');
        document.getElementById('hud-2p').classList.add('hidden');
        document.getElementById('game-over-screen').classList.remove('hidden');
        let winnerIndex = null;

        if (state.session.numPlayers === 2) {
            document.getElementById('game-over-screen').classList.add('mode-2p');
            // Hide score row — only show winner banner + stats
            document.getElementById('score-row').style.display = 'none';
            document.getElementById('final-p2-container').classList.remove('hidden');

            // players[0] = LEFT board = currentPlayerName (entered first)
            // players[1] = RIGHT board = currentPlayer2Name (entered second)
            // Stats cards: final-p1-name = LEFT, final-p2-name = RIGHT
            document.getElementById('final-p1-stats-name').classList.remove('hidden');
            document.getElementById('final-p1-stats-name').innerText = state.session.currentPlayerName;
            document.getElementById('final-p2-stats-name').innerText = state.session.currentPlayer2Name;
            document.getElementById('final-p1-squats').innerText = state.game.players[0].stats.squats;
            document.getElementById('final-p1-jumps').innerText = state.game.players[0].stats.jumps;
            document.getElementById('final-p1-energy').textContent = app.energy.readEnergy(state.game.players[0]).toFixed(1);
            document.getElementById('final-p2-squats').innerText = state.game.players[1].stats.squats;
            document.getElementById('final-p2-jumps').innerText = state.game.players[1].stats.jumps;
            document.getElementById('final-p2-energy').textContent = app.energy.readEnergy(state.game.players[1]).toFixed(1);

            // Winner = whoever still has lives (survivor wins)
            let winnerName, winnerScore;
            if (state.game.players[0].lives <= 0 && state.game.players[1].lives > 0) {
                winnerIndex = 1;
                winnerName  = state.session.currentPlayer2Name;
                winnerScore = Math.floor(state.game.players[1].score || 0);
            } else if (state.game.players[1].lives <= 0 && state.game.players[0].lives > 0) {
                winnerIndex = 0;
                winnerName  = state.session.currentPlayerName;
                winnerScore = Math.floor(state.game.players[0].score || 0);
            } else {
                // Both died simultaneously — higher score wins
                const p0 = Math.floor(state.game.players[0].score || 0);
                const p1 = Math.floor(state.game.players[1].score || 0);
                winnerIndex = p0 >= p1 ? 0 : 1;
                winnerName  = p0 >= p1 ? state.session.currentPlayerName : state.session.currentPlayer2Name;
                winnerScore = Math.max(p0, p1);
            }

            document.getElementById('winner-banner').classList.remove('hidden');
            document.getElementById('winner-name').innerText  = winnerName;
            document.getElementById('winner-score').innerText = winnerScore;

            // Show winner stamp on the correct stats card
            document.getElementById('winner-stamp-p1').classList.remove('show');
            document.getElementById('winner-stamp-p2').classList.remove('show');
            const stampId = winnerIndex === 0 ? 'winner-stamp-p1' : 'winner-stamp-p2';
            setTimeout(() => document.getElementById(stampId).classList.add('show'), 400);
        } else {
            // Single player
            document.getElementById('game-over-screen').classList.remove('mode-2p');
            document.getElementById('final-p1-name').innerText = state.session.currentPlayerName;
            document.getElementById('final-p1-stats-name').classList.add('hidden');
            document.getElementById('score-row').style.display = '';
            document.getElementById('final-score').innerText = Math.floor(state.game.score);
            document.getElementById('final-p1-squats').innerText = state.game.players[0].stats.squats;
            document.getElementById('final-p1-jumps').innerText = state.game.players[0].stats.jumps;
            document.getElementById('final-p1-energy').textContent = app.energy.readEnergy(state.game.players[0]).toFixed(1);
            document.getElementById('final-p2-container').classList.add('hidden');
            document.getElementById('winner-banner').classList.add('hidden');
        }

        // Health tip
        const tip = app.tutorial.HEALTH_TIPS[Math.floor(Math.random() * app.tutorial.HEALTH_TIPS.length)];
        document.getElementById('health-tip-title').textContent = tip.title;
        document.getElementById('health-tip-body').textContent = tip.body;
        app.finishPhoto.showFinishPhoto(winnerIndex);
    }

    return { startGameplay, gameOver };
}

// Source: src/game/simulation.js
/** simulation: see docs/architecture.md for ownership and compatibility rules. */
function createSimulation({ state, app }) {
    const STEP_MS = 1000 / 60;
    const MAX_GAP_MS = 250;
    let lastFrameAt, remainder = 0;

    function resetFrameClock() {
        lastFrameAt = undefined;
        remainder = 0;
    }
    document.addEventListener('visibilitychange', resetFrameClock);
    function spawnObstacle() {
        let availableTypes = ['high', 'low', 'block'];
        if (state.game.score > 100) availableTypes.push('low-wide');
        if (state.game.score > 200) availableTypes.push('door');

        const type = availableTypes[Math.floor(Math.random() * availableTypes.length)];
        let lane = [-1, 0, 1][Math.floor(Math.random() * 3)];
        let span = 1;

        if (type === 'low-wide') { lane = 0; span = 3; }
        else if (type === 'door') {
            span = Math.floor(Math.random() * 3) + 1;
            if (span === 3) { lane = 0; }
            else if (span === 2) { lane = Math.random() < 0.5 ? -0.5 : 0.5; }
        }
        state.game.obstacles.push({ lane, span, depth: 0, type, active: true });
    }

    function advanceFrame() {
        if (app.trackingSafety.isGameplayPaused()) return true;
        state.game.frameCount++;

        // --- Orb notify timer ---
        if (state.game.orbNotifyTimer > 0) {
            state.game.orbNotifyTimer--;
            if (state.game.orbNotifyTimer === 0) app.notifications.clearOrbNotify();
        }

        // --- Shield timer tick ---
        for (let i = 0; i < state.session.numPlayers; i++) {
            let p = state.game.players[i];
            if (p.shieldActive) {
                p.shieldTimer--;
                if (p.shieldTimer <= 0) {
                    p.shieldActive = false;
                    p.shieldTimer = 0;
                    app.feedback.hideShieldActive();
                    // No notification — shield just quietly ends
                }
            }
        }

        if (state.game.levelUpTimer > 0) {
            state.game.levelUpTimer--;
            if (state.game.levelUpTimer === 0) app.feedback.hideLevelUp();
        }

        // Score and obstacle spawning always run (independent of levelUpTimer display)
        {
            state.game.score += (state.game.speed / 100);
            // Track per-player score based on survival
            for (let i = 0; i < state.session.numPlayers; i++) {
                if (state.game.players[i].active && !state.game.players[i].eliminated) {
                    state.game.players[i].score = (state.game.players[i].score || 0) + (state.game.speed / 100);
                }
            }
            state.game.speed = (4 + (state.game.score / 100)) * state.game.speedMultiplier;

            if (state.game.blockRestTimer > 0) state.game.blockRestTimer--;

            if (state.game.score >= state.game.nextMilestone && state.game.nextMilestone <= 400) {
                state.game.levelUpTimer = 300;
                state.game.blockRestTimer = 240; // 4-second block-free rest
                let msg = "";
                if (state.game.nextMilestone === 100) msg = "Fly over three row obstacles!";
                else if (state.game.nextMilestone === 200) msg = "Duck under the door frames!";
                else if (state.game.nextMilestone === 300) msg = "You are a moving star!";
                else if (state.game.nextMilestone === 400) msg = "You are a legend!";
                // Upgrade sky style every 100 pts (0→1→2→3→4)
                state.game.skyStyle = Math.min(state.game.skyStyle + 1, 4);
                app.feedback.showLevelUp(msg);
                app.audio.playSynth('levelup');
                state.game.nextMilestone += 100;
            } else if (state.game.blockRestTimer === 0) {
                let baseSpawnRate = Math.max(40, 100 - Math.floor((4 + state.game.score/100) * 3));
                let spawnRate = Math.floor(baseSpawnRate / state.game.speedMultiplier);
                if (state.game.frameCount % spawnRate === 0) spawnObstacle();
                // Score-based orb spawning — shields every 50, hearts every 100
                if (Math.floor(state.game.score) >= state.game.nextShieldScore) {
                    // Spawn a shield orb at a random lane
                    const lane = [-1, 0, 1][Math.floor(Math.random() * 3)];
                    state.game.orbs.push({ lane, depth: 0, type: 'shield', active: true, bobOffset: Math.random() * Math.PI * 2 });
                    state.game.nextShieldScore += 50;
                    // Show notification
                    app.notifications.showOrbNotify('🛡️ Shield orb incoming!', 'rgba(6,182,212,0.95)');
                }

                if (Math.floor(state.game.score) >= state.game.nextHeartScore) {
                    // Spawn a heart orb at a random lane
                    const lane = [-1, 0, 1][Math.floor(Math.random() * 3)];
                    state.game.orbs.push({ lane, depth: 0, type: 'heart', active: true, bobOffset: Math.random() * Math.PI * 2 });
                    state.game.nextHeartScore += 100;
                    // Show notification
                    app.notifications.showOrbNotify('💗 Heart orb incoming!', 'rgba(236,72,153,0.95)');
                }
            }
        }

        // Update obstacles
        state.game.obstacles.forEach(obs => {
            if (obs.active) {
                obs.depth += (state.game.speed * 0.001) + (obs.depth * 0.02);
                if (obs.depth > 1.2) obs.active = false;
            }
        });

        // Update orbs
        state.game.orbs.forEach(orb => {
            if (orb.active) {
                orb.depth += (state.game.speed * 0.001) + (orb.depth * 0.02);
                if (orb.depth > 1.2) orb.active = false;
            }
        });

        const playerDepth = 0.85;

        // --- Collision: obstacles ---
        for (let i = 0; i < state.session.numPlayers; i++) {
            let p = state.game.players[i];
            if (p.invulnerableFrames > 0) p.invulnerableFrames--;
            if (p.lives <= 0) continue;

            for (let obs of state.game.obstacles) {
                if (!obs.active || p.invulnerableFrames > 0) continue;
                if (obs.depth > playerDepth - 0.1 && obs.depth < playerDepth + 0.1) {
                    let isHitLane = Math.abs(p.lane - obs.lane) <= (obs.span - 1) / 2 + 0.01;
                    if (isHitLane) {
                        let hit = false;
                        if (obs.type === 'block') hit = true;
                        else if ((obs.type === 'high' || obs.type === 'door') && !p.isSquatting) hit = true;
                        else if ((obs.type === 'low' || obs.type === 'low-wide') && !p.isJumping) hit = true;

                        if (hit) {
                            if (p.shieldActive) {
                                // Shield absorbs the hit silently — just destroy obstacle
                                obs.active = false;
                                app.audio.playSynth('orb');
                            } else {
                                p.lives--; app.hud.updateHUD(); app.audio.playSynth('hit');
                                if (p.lives > 0) p.invulnerableFrames = 60;
                            }
                        }
                    }
                }
            }

            // --- Collision: orbs — completely ignored during shield/rest period ---
            if (!p.shieldActive && !p.restingMode) {
                for (let orb of state.game.orbs) {
                    // In 2P mode each orb tracks which players have collected it
                    if (state.session.numPlayers === 2) {
                        if (!orb.collectedBy) orb.collectedBy = [];
                        if (orb.collectedBy.includes(i)) continue; // this player already collected it
                    } else {
                        if (!orb.active) continue;
                    }
                    if (orb.depth > playerDepth - 0.12 && orb.depth < playerDepth + 0.12) {
                        if (Math.abs(p.lane - orb.lane) < 0.6) {
                            if (state.session.numPlayers === 2) {
                                orb.collectedBy.push(i);
                                // Deactivate only when both players have collected or passed
                                if (orb.collectedBy.length >= 2) orb.active = false;
                            } else {
                                orb.active = false;
                            }
                            if (orb.type === 'shield') {
                                p.shieldOrbs++;
                                app.hud.updateHUD();
                                app.audio.playSynth('orb');
                                app.notifications.showOrbNotify(`🛡️ +1 Shield!`, 'rgba(6,182,212,0.95)');
                            } else if (orb.type === 'heart') {
                                p.lives = Math.min(p.lives + 1, 9);
                                app.hud.updateHUD();
                                app.audio.playSynth('heart');
                                app.notifications.showOrbNotify('💗 +1 Life!', 'rgba(236,72,153,0.95)');
                            }
                        }
                    }
                }
            }
        }

        // Game ends as soon as any player hits 0 lives
        let anyDead = false;
        for (let i=0; i<state.session.numPlayers; i++) {
            if (state.game.players[i].lives <= 0) anyDead = true;
        }
        if (anyDead) { app.session.gameOver(); return false; }

        state.game.obstacles = state.game.obstacles.filter(o => o.active);
        state.game.orbs = state.game.orbs.filter(o => o.active);
        if (state.game.frameCount % 10 === 0) app.hud.updateHUD();

        return true;
    }

    function gameLoop(timestamp) {
        if (state.game.gameState !== 'playing') { resetFrameClock(); return; }
        app.pose.checkPlayerTracking();
        app.energy.updateEnergy();
        if (app.trackingSafety.isGameplayPaused() || document.hidden) {
            resetFrameClock();
        } else {
            // The immediate session-start call retains its original first step.
            // After a pause the first callback starts a new clock, with no debt.
            let steps = 1;
            if (Number.isFinite(timestamp)) {
                if (lastFrameAt !== undefined) {
                    const elapsed = timestamp - lastFrameAt;
                    if (elapsed < 0 || elapsed > MAX_GAP_MS) {
                        remainder = 0;
                        steps = 0;
                    } else {
                        remainder += elapsed;
                        steps = Math.floor((remainder + 1e-7) / STEP_MS);
                        remainder = Math.max(0, remainder - steps * STEP_MS);
                    }
                }
                lastFrameAt = timestamp;
            }
            for (let step = 0; step < steps; step++) {
                if (!advanceFrame()) { resetFrameClock(); return; }
                // Keep random/animation updates between simulation steps in
                // their original viewport order. Only the last step paints.
                if (step === steps - 1) app.scene.renderGameplay();
                else app.scene.advanceVisualFrame();
            }
        }
        state.game.gameLoopId = requestAnimationFrame(gameLoop);
    }

    return { spawnObstacle, advanceFrame, gameLoop, resetFrameClock };
}

// Source: src/ui/warning.js
/** warning: see docs/architecture.md for ownership and compatibility rules. */
function createWarning({ state, app }) {
    const WARNING_READ_PLAY_ICON = `<polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"></polygon><path d="M15.54 8.46a5 5 0 0 1 0 7.07"></path><path d="M19.07 4.93a10 10 0 0 1 0 14.14"></path>`;
    const WARNING_READ_STOP_ICON = `<line x1="1" y1="1" x2="23" y2="23"></line><polygon points="9 9 11 5 11 19 6 15 2 15 2 9 9 9"></polygon><path d="M15.54 8.46a5 5 0 0 1 1.46 3.54"></path>`;

    function resetWarningReadBtn() {
        const btn = document.getElementById('warning-read-btn');
        const icon = document.getElementById('warning-read-icon');
        if (!btn || !icon) return;
        icon.innerHTML = WARNING_READ_PLAY_ICON;
        btn.classList.remove('bg-amber-300', 'dark:bg-amber-700');
        btn.setAttribute('aria-pressed', 'false');
    }

    function stopWarningAudio() {
        const audio = document.getElementById('warning-audio');
        if (audio) {
            audio.pause();
            audio.currentTime = 0;
        }
        resetWarningReadBtn();
    }

    function toggleWarningRead() {
        const btn = document.getElementById('warning-read-btn');
        const icon = document.getElementById('warning-read-icon');
        const audio = document.getElementById('warning-audio');
        if (!btn || !icon || !audio) return;

        if (!audio.paused) {
            stopWarningAudio();
            return;
        }

        audio.currentTime = 0;
        audio.play().then(() => {
            icon.innerHTML = WARNING_READ_STOP_ICON;
            btn.classList.add('bg-amber-300', 'dark:bg-amber-700');
            btn.setAttribute('aria-pressed', 'true');
        }).catch(() => stopWarningAudio());

        audio.onended = stopWarningAudio;
        audio.onerror = stopWarningAudio;
    }

    return { WARNING_READ_PLAY_ICON, WARNING_READ_STOP_ICON, resetWarningReadBtn, stopWarningAudio, toggleWarningRead };
}

